create policy "Anyone can submit contact messages"
  on public.contact_messages
  for insert
  with check (true);

-- R2: Enforce status defaults and handled_by null on insert (defense in depth)
create function enforce_contact_message_defaults()
returns trigger as $$
begin
  new.status := coalesce(new.status, 'new');
  new.handled_by := null;
  return new;
end;
$$ language plpgsql security definer;

create trigger enforce_contact_message_defaults_trigger
  before insert on public.contact_messages
  for each row
  execute function enforce_contact_message_defaults();

-- R3: Nobody can read, update, or delete messages through the app
