```sql
-- Enable RLS on all relevant tables
alter table public.courses enable row level security;
alter table public.lessons enable row level security;
alter table public.enrollments enable row level security;

-- =========================
-- COURSES POLICIES
-- =========================

-- R1: Anyone can read published courses; instructors can read their own unpublished courses
create policy "Anyone can read published courses" on public.courses
for select using (is_published = true);

create policy "Instructors can read own unpublished courses" on public.courses
for select using (
  instructor_id = auth.uid() and is_published = false
);

-- R2: Signed-in users can create courses as their instructor; instructors can edit/delete own courses
create policy "Instructors can create courses" on public.courses
for insert with check (instructor_id = auth.uid());

create policy "Instructors can update own courses" on public.courses
for update using (instructor_id = auth.uid())
with check (instructor_id = auth.uid());

create policy "Instructors can delete own courses" on public.courses
for delete using (instructor_id = auth.uid());

-- =========================
-- LESSONS POLICIES
-- =========================

-- R3: Anyone can read preview lessons of published courses
-- Students enrolled in a published course can read all its lessons
-- Instructors can read, create, edit and delete every lesson of their own courses
create policy "Anyone can read preview lessons of published courses" on public.lessons
for select using (
  is_preview = true and exists (
    select 1 from public.courses where id = course_id and is_published = true
  )
);

create policy "Enrolled students can read all lessons of published courses" on public.lessons
for select using (
  exists (
    select 1 from public.enrollments where course_id = public.courses.id and student_id = auth.uid()
  ) and exists (
    select 1 from public.courses where id = course_id and is_published = true
  )
);

create policy "Instructors can CRUD own lessons" on public.lessons
for all using (instructor_id = auth.uid())
with check (instructor_id = auth.uid());

-- =========================
-- ENROLLMENTS POLICIES
-- =========================

-- R4: Signed-in users can enroll themselves in published courses and remove own enrollments
-- Nobody can enroll someone else
create policy "Users can enroll themselves in published courses" on public.enrollments
for insert with check (
  course_id in (
    select id from public.courses where is_published = true
  ) and student_id = auth.uid()
);

create policy "Users can remove own enrollments" on public.enrollments
for delete using (student_id = auth.uid());

-- R5: Students can see their own enrollments, instructors can see enrollments in their courses
create policy "Students can see own enrollments" on public.enrollments
for select using (student_id = auth.uid());

create policy "Instructors can see enrollments in own courses" on public.enrollments
for select using (
  exists (
    select 1 from public.courses where id = course_id and instructor_id = auth.uid()
  )
);

-- =========================
-- GRANTS/REVOKES
-- =========================

-- Ensure anon role cannot change anything (R6)
-- Supabase anon already has limited permissions, but explicitly revoke insert/update/delete on these tables for anon
revoke insert, update, delete on public.courses from anon;
revoke insert, update, delete on public.lessons from anon;
revoke insert, update, delete on public.enrollments from anon;

-- service_role keeps full access (R7) - already implicit, but ensure it's not restricted
grant all on public.courses to service_role;
grant all on public.lessons to service_role;
grant all on public.enrollments to service_role;
