-- Enable Row Level Security on all relevant tables
alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

-- R1: Users can read only their own wallet
create policy "Users can read own wallet" on public.wallets
for select using (user_id = auth.uid());

-- R2: Users can read transfers they sent or received
create policy "Users can read own transfers" on public.transfers
for select using (from_user = auth.uid() or to_user = auth.uid());

-- R3: No direct DML on wallets or transfers (enforced via restrictive policies)
-- Allow service_role full access (R5) and deny all other operations
create policy "Service role full access" on public.wallets
for all using (auth.role() = 'service_role');
create policy "Deny all DML on wallets" on public.wallets
for insert, update, delete with check (false);

create policy "Service role full access transfers" on public.transfers
for all using (auth.role() = 'service_role');
create policy "Deny all DML on transfers" on public.transfers
for insert, update, delete with check (false);

-- R4: send_points RPC implementation
-- Helper function to check if recipient has a wallet
create or replace function public.has_wallet(p_user_id uuid)
returns boolean language sql security invoker as $$
  select exists (select 1 from public.wallets where user_id = p_user_id);
$$;

-- The main RPC function
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint language plpgsql security definer as $$
declare
  v_from_user uuid;
  v_from_balance integer;
  v_to_balance integer;
  v_new_transfer_id bigint;
begin
  -- Check: caller must be signed in
  if auth.role() != 'authenticated' then
    raise exception 'User not signed in';
  end if;
  v_from_user := auth.uid();

  -- Check: amount must be positive
  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  -- Check: caller must have enough points
  select balance into v_from_balance from public.wallets where user_id = v_from_user for update;
  if v_from_balance is null or v_from_balance < p_amount then
    raise exception 'Insufficient points';
  end if;

  -- Check: recipient must have a wallet and not be the caller
  if p_to = v_from_user then
    raise exception 'Cannot send points to yourself';
  end if;
  if not public.has_wallet(p_to) then
    raise exception 'Recipient has no wallet';
  end if;

  -- Perform the transfer within a transaction
  -- Deduct from sender
  update public.wallets set balance = balance - p_amount where user_id = v_from_user;

  -- Add to recipient
  update public.wallets set balance = balance + p_amount where user_id = p_to;

  -- Record the transfer
  insert public.transfers (from_user, to_user, amount, created_at)
  values (v_from_user, p_to, p_amount, now())
  returning id into v_new_transfer_id;

  return v_new_transfer_id;
end;
$$;

-- R5: Grants for service_role (full access already via policies, but explicit grant for clarity)
grant all on public.wallets to service_role;
grant all on public.transfers to service_role;
grant execute on function public.send_points to service_role;
