-- Enable RLS on all relevant tables
alter table public.wallets enable row level security;
alter table public.transfers enable row level security;

-- Helper function to get current user id safely
create or replace function public.current_user_id()
returns uuid language sql security definer as $$
  select coalesce(auth.uid()::uuid, '00000000-0000-0000-0000-000000000000'::uuid);
$$;

-- R1: Users can read only their own wallet
create policy "Users can read own wallet"
  on public.wallets for select
  using (user_id = public.current_user_id());

-- R2: Users can read transfers they sent or received
create policy "Users can read own transfers"
  on public.transfers for select
  using (from_user = public.current_user_id() or to_user = public.current_user_id());

-- R3 & R4: send_points RPC implementation
-- This RPC moves points and records a transfer. 
-- It runs with security definer so service_role behavior is handled, 
-- but we also grant access to authenticated users to execute it.
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint language plpgsql security definer as $$
declare
  v_from uuid;
  v_from_balance integer;
  v_to_user auth.users%rowtype;
  v_to_id uuid;
  v_new_from_balance integer;
  v_new_to_balance integer;
  v_transfer_id bigint;
begin
  -- Check: caller must be signed in
  v_from := auth.uid();
  if v_from is null then
    raise exception 'Caller is not signed in';
  end if;

  -- Check: amount must be positive
  if p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;

  -- Check: recipient must exist in auth.users
  select * into v_to_user from auth.users where id = p_to;
  if not found then
    raise exception 'Recipient does not exist';
  end if;
  v_to_id := p_to;

  -- Check: recipient must have a wallet
  if not exists (select 1 from public.wallets where user_id = v_to_id) then
    raise exception 'Recipient has no wallet';
  end if;

  -- Check: caller must not send to themselves
  if v_from = v_to_id then
    raise exception 'Caller cannot send points to themselves';
  end if;

  -- Check: caller must have enough points
  select balance into v_from_balance from public.wallets where user_id = v_from;
  if v_from_balance is null then
    raise exception 'Caller has no wallet';
  end if;
  if v_from_balance < p_amount then
    raise exception 'Insufficient points';
  end if;

  -- Perform the transfer inside a transaction
  -- Update from_user wallet
  update public.wallets set balance = balance - p_amount where user_id = v_from;
  -- Update to_user wallet
  update public.wallets set balance = balance + p_amount where user_id = v_to_id;
  -- Record the transfer
  insert public.transfers (from_user, to_user, amount, created_at)
    values (v_from, v_to_id, p_amount, now())
    returning id into v_transfer_id;

  return v_transfer_id;
end;
$$;

-- Grant execute on the RPC to authenticated users
grant execute on function public.send_points(uuid, integer) to authenticated;

-- R5: Service role keeps full access (already implicit, but explicit grant for clarity)
grant all on public.wallets to service_role;
grant all on public.transfers to service_role;
grant all on public.wallets to authenticated with grant option;
grant all on public.transfers to authenticated with grant option;
