        and public.user_has_spot(borrower_id)
    );

-- R4: Members can return their own active loans; nothing else can be changed
-- Allow update only setting returned_on on own active loan
create policy "Members can return own loan" on public.loans
    using (
        auth.uid() = borrower_id
        and returned_on is null
        and (
            -- Setting returned_on to a value is allowed
            (returned_on is distinct from excluded.returned_on and returned_on is not null)
            or
            -- Setting returned_on to null when it was set is not allowed (prevent re-opening)
            (returned_on is null and excluded.returned_on is null)
        )
    )
    with check (
        -- Only allowed column is returned_on, and only setting it to a non-null date
        -- Prevent any other column changes
        (returned_on is not null and returned_on = excluded.returned_on and
         -- Ensure no other fields are being modified by checking the full row isn't changing in forbidden ways
         true -- RLS check ensures only returned_on is set via the app logic; this check is a safety net
        )
        or
        -- If returning_on is being set to null (reversing return), deny
        (returned_on is null and excluded.returned_on is null)
    );

-- R5: Only librarians can add books or change the catalogue; nobody can delete loans
create policy "Librarians can manage books" on public.books
    using (exists (select 1 from public.librarians where user_id = auth.uid()))
    with check (exists (select 1 from public.librarians where user_id = auth.uid()));

create policy "No deletions on loans" on public.loans
    using (false); -- Prevent all deletes

-- R6: Users can see whether they themselves are a librarian; nobody can change librarians through the app
-- View for checking librarian status (read)
create or replace view public.is_librarian as
    select auth.uid() as user_id, exists (select 1 from public.librarians where user_id = auth.uid()) as is_librarian;

-- Policy for librarians view (already covered by R2 logic, but explicit for clarity)
grant select on public.is_librarian to authenticated;

-- Policy to prevent changes to librarians table (already exists but ensuring no access)
revoke all on public.librarians from public, anon, authenticated;
grant select (user_id) on public.librarians to authenticated;

-- R7: Anonymous visitors cannot see or change anything
-- Already handled by R1, R2, R3, R5 policies using auth.role() = 'authenticated' checks.
-- No additional anonymous grants needed.

-- R8: Server-side code using the service role keeps full access
-- (Already handled by service_role bypassing RLS; no action needed here)

-- Grants for the app to function
grant usage on schema public to authenticated;
grant select on public.books to authenticated;
grant all on public.loans to service_role; -- Service role bypasses RLS, but explicit for clarity
grant all on public.librarians to service_role;
