      where mgr.user_id = auth.uid()
        and mgr.user_id = (select manager_id from public.employees where user_id = employee_id)
    )
  );

-- R2: Employees can create leave requests for themselves only; new requests pending, no decided_by
create policy "Employees create own leave requests" on public.leave_requests
  for insert with check (
    employee_id = auth.uid()
    and status = 'pending'
    and decided_by is null
  );

-- R3: While pending, employee can change dates/note/cancel; cannot approve/reject own request
create policy "Employees update pending leave requests" on public.leave_requests
  for update using (
    employee_id = auth.uid()
    and status = 'pending'
  )
  with check (
    employee_id = auth.uid()
    and status in ('pending', 'cancelled')
    and (ends_on >= starts_on)  -- check constraint preserved
  );

-- R4: Direct manager can approve/reject pending request of their report, recording themselves in decided_by
--     Deciding cannot change dates or note
create policy "Managers approve/reject pending leave requests" on public.leave_requests
  for update using (
    exists (
      select 1 from public.employees mgr
      where mgr.user_id = auth.uid()
        and mgr.user_id = (select manager_id from public.employees where user_id = employee_id)
    )
    and status = 'pending'
  )
  with check (
    -- Only status and decided_by may change; dates and note must remain unchanged
    -- We compare the row's current values against the proposed new values via the update
    -- Since with check validates the new row, we enforce that ends_on, starts_on, note are unchanged
    -- by ensuring they match the existing row values. Supabase RLS with check does not auto-
    -- compare old/new, so we enforce here using a stored function pattern; however, to keep
    -- everything in pure SQL policies we rely on the app sending only status/decided_by.
    -- The following restricts updates to only status and decided_by being set.
    -- We allow the update if the new status is approved/rejected and decided_by is set,
    -- or if the status remains pending (handled by other policy). For simplicity and
    -- correctness per the rules, we permit the update when the manager sets status
    -- to approved/rejected and provides decided_by, and we prevent changing ends_on/starts_on/note.
    -- Supabase does not support "old row" comparison in policies directly, so we use a
    -- trigger-based approach (see below). This policy allows the update; the trigger enforces
    -- the "no date/note change" rule.
    true  -- placeholder; actual enforcement via trigger below
  );

-- R5: Once not pending, nobody can change it; requests never deleted
create policy "No changes to non-pending leave requests" on public.leave_requests
  for update using (status != 'pending')
  with check (false);

create policy "No deletion of leave requests" on public.leave_requests
  for delete using (false);

-- Helper function to enforce "deciding cannot change dates or note"
-- This function is called via trigger on leave_requests updates
create or replace function public.enforce_leave_request_update()
returns trigger as $$
begin
  -- If the request is no longer pending, reject the update (R5)
  if (status != 'pending' and old.status = 'pending') then
    -- R5: once not pending, nobody can change it
    -- The "No changes to non-pending" policy already blocks this, but we keep guard here.
    raise exception 'Cannot update a leave request that is no longer pending';
  end if;

  -- R4: When a manager is deciding (setting status to approved/rejected),
  --     ensure ends_on and starts_on and note are not changed.
  -- We compare new values to old values.
  if (old.status = 'pending' and new.status in ('approved','rejected')) then
    if (new.ends_on != old.ends_on) then
      raise exception 'Cannot change ends_on when approving/rejecting';
    end if;
    if (new.starts_on != old.starts_on) then
      raise exception 'Cannot change starts_on when approving/rejecting';
    end if;
    if (new.note != old.note) then
      raise exception 'Cannot change note when approving/rejecting';
    end if;
  end if;

  -- Ensure decided_by is set when status changes to approved/rejected
  if (new.status in ('approved','rejected') and new.decided_by is null) then
    raise exception 'decided_by must be set when status is approved/rejected';
  end if;

  return new;
end;
$$ language plpgsql security definer;

-- Attach trigger on leave_requests updates
create trigger enforce_leave_request_update_trigger
  after update on public.leave_requests
  for each row
  execute function public.enforce_leave_request_update();

-- R6: Signed-in users can read the employee directory; nobody can change employees
-- (already covered by the "Employees no changes" policy above)
grant usage on schema public to authenticated;
grant select on public.employees to authenticated;

-- R7: Anonymous visitors cannot see or change anything
-- revoke all anonymous access; policies with `using (false)` already block anon,
-- but explicitly revoke to be safe.
revoke all on public.employees from anon;
revoke all on public.leave_requests from anon;

-- R8: Server-side code using the service role keeps full access
-- service_role bypasses RLS by default; no additional grant needed.
