    for delete using (author_id = auth.uid());

-- ============================================================
-- Friendships policies
-- ============================================================

-- R3: Users can send friend requests as the requester (always pending)
-- The requester_id is set by the client, we enforce it matches the signed-in user
create policy "users_send_friend_request" on public.friendships
    for insert with check (requester_id = auth.uid());

-- R4: Only the addressee of a pending request can accept it
-- Accept: only addressee can accept a pending request
create policy "addressee_accept_friend_request" on public.friendships
    for update using (
        status = 'pending' 
        and addressee_id = auth.uid()
    )
    with check (
        status = 'accepted' 
        and addressee_id = auth.uid()
    );

