returns trigger as $$
begin
  -- If updating is_featured, always reject (enforced by policy, but defense in depth)
  if new.is_featured is distinct from old.is_featured then
    raise exception 'cannot change is_featured';
  end if;
  -- Ensure the user is the owner
  if new.user_id != auth.uid() then
    raise exception 'cannot change another user''s review';
  end if;
  -- For insert, ensure the user has purchased the product (enforced by policy insert check too)
  if TG_OP = 'INSERT' then
    if not exists (
      select 1 from public.purchases
      where user_id = auth.uid()
      and product_id = new.product_id
    ) then
      raise exception 'must purchase product before reviewing';
    end if;
  end if;
  return new;
end;
$$ language plpgsql security invoker;

