-- Helper function to prevent modifications in locked periods
create or replace function public.prevent_locked_period() returns trigger language plpgsql security definer as $$
declare
  v_period_id bigint;
  v_is_locked boolean;
begin
  -- Determine the period_id involved in the operation
  if TG_OP = 'DELETE' then
    v_period_id := old.period_id;
  else
    v_period_id := new.period_id;
  end if;

  -- Check if the period is locked
  select is_locked into v_is_locked from public.periods where id = v_period_id;

  if v_is_locked then
    raise exception 'Cannot modify time entries in a locked period (period_id: %)', v_period_id using errcode = 'restricted_operation';
  end if;

  return case when TG_OP = 'DELETE' then old else new end;
end;
$$;

