  for insert with check (owner_id = auth.uid());

-- RLS Policy: Users can rename and delete their own files (R2)
create policy "Users can modify own files" on public.files
  for update using (owner_id = auth.uid())
  with check (owner_id = auth.uid());

create policy "Users can delete own files" on public.files
  for delete using (owner_id = auth.uid());

-- RLS Policy: Org admins can rename and delete any file (R2)
create policy "Org admins can modify all files" on public.files
  for update using (
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
  );

create policy "Org admins can delete all files" on public.files
  for delete using (
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
  );

-- R3: Legal hold prevents rename/delete by anyone including owner and org admins
-- This is enforced via a check option that rejects updates/deletes when legal_hold is true
-- The existing policies already have `with check` clauses; we add an additional
-- restriction by modifying the check to reject when legal_hold is true.

-- Create a helper function to encapsulate the legal hold check (R3)
create or replace function public.check_legal_hold()
returns trigger as $$
begin
  if new.legal_hold = true then
    -- Prevent any modification when legal_hold is set
    return new;
  end if;
  return new;
end;
$$ language plpgsql;

-- Apply legal hold check to update policy (R3)
-- We re-create the org admin modify policy with the legal hold condition in with check
drop policy if exists "Org admins can modify all files" on public.files;
create policy "Org admins can modify all files (legal hold aware)" on public.files
  for update using (
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
  )
  with check (
    -- Must be an org admin AND file must not be under legal hold
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
    and new.legal_hold = false
  );

-- Apply legal hold check to user own modify policy (R3)
drop policy if exists "Users can modify own files" on public.files;
create policy "Users can modify own files (legal hold aware)" on public.files
  for update using (owner_id = auth.uid())
  with check (owner_id = auth.uid() and new.legal_hold = false);

drop policy if exists "Users can delete own files" on public.files;
create policy "Users can delete own files (legal hold aware)" on public.files
  for delete using (owner_id = auth.uid() and (select legal_hold from public.files where id = old.id) = false);

-- R3: Delete policy for org admins (legal hold aware)
drop policy if exists "Org admins can delete all files" on public.files;
create policy "Org admins can delete all files (legal hold aware)" on public.files
  for delete using (
    exists (
      select 1 from public.org_admins
      where user_id = auth.uid()
    )
    and (select legal_hold from public.files where id = old.id) = false
  );

-- R4: Nobody can place or lift a legal hold through the app
-- We prevent any update that modifies the legal_hold column.
-- The policies above already restrict updates when legal_hold is true,
-- but we also need to block setting it to true or false.
-- We add a check that legal_hold must remain unchanged, effectively blocking any toggle.
-- Since we cannot easily compare old/new legal_hold in a simple using clause without
-- a trigger, we create a trigger that rejects any update changing legal_hold.

-- Create trigger to prevent legal hold changes through the app (R4)
create trigger prevent_legal_hold_change
  before update on public.files
  for each row
  execute function public.prevent_legal_hold_update();

-- Helper function for the trigger
create or replace function public.prevent_legal_hold_update()
returns trigger as $$
begin
  if new.legal_hold != old.legal_hold then
    raise exception 'Legal hold cannot be changed through the app';
  end if;
  return new;
end;
$$ language plpgsql;

-- R5: Nobody can change org_admins through the app
-- org_admins table has no DML policies needed for R5 if we simply revoke all
-- public access and rely on service_role only. We'll add a deny policy.

-- Revoke all default permissions on org_admins
revoke all on public.org_admins from public;
revoke all on public.org_admins from authenticated;

-- Create policy to completely block access to org_admins from app users (R5)
create policy "No access to org_admins from app" on public.org_admins
  using (false)
  with check (false);

-- R6: Anonymous visitors cannot see or change anything
-- Since policies use auth.uid(), anon users will fail authentication check automatically.
-- No additional policy needed; the existing policies deny anon by design.

-- R7: Server-side code using the service role keeps full access
-- service_role bypasses RLS by default; no additional action needed.

-- Grants to ensure the above work (adjust as needed for your project)
-- Grant usage on schemas if not already public
