-- R3: accept_invite function
create or replace function public.accept_invite(p_token text) returns bigint language sql strict as $$
declare
  v_org_id bigint;
  v_email text;
  v_invited_by uuid;
  v_role text;
  v_expires_at timestamptz;
  v_accepted_at timestamptz;
  v_invitee_email text;
begin
  -- 1. Must be signed in
  if auth.uid() is null then
    raise exception 'User not signed in';
  end if;

  -- 2. Token must exist and not be accepted yet
  select email, org_id, role, expires_at, accepted_at, invited_by
  into v_invitee_email, v_org_id, v_role, v_expires_at, v_accepted_at, v_invited_by
  from public.invites
  where token = p_token;

  if not found then
    raise exception 'Unknown token';
  end if;

  if v_accepted_at is not null then
    raise exception 'Invite already accepted';
  end if;

  -- 3. Check expiration
  if now() > v_expires_at then
    raise exception 'Invite expired';
  end if;

  -- 4. Verify caller's verified email matches invite email (case-insensitive)
  select lower(email) from auth.users where id = auth.uid() into v_invitee_email;
  if lower(coalesce(v_invitee_email, '')) != lower(coalesce(v_invitee_email, '')) then
    -- Compare the invite's stored email with the user's verified email
    if lower(coalesce((select email from auth.users where id = auth.uid()), '')) != lower(coalesce(v_invitee_email, '')) then
      raise exception 'Email mismatch: invite email does not match verified user email';
    end if;
  end if;

  -- 5. Add user to org_members with the invite's role
  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_role);

  -- 6. Mark invite as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

