  for all using (false);

-- Helper function to normalize email for case-insensitive comparison
create or replace function public.normalize_email(email text)
returns text language sql immutable as $$
  select lower(trim($1));
$$;

-- Accept invite RPC function
create or replace function public.accept_invite(p_token text)
returns bigint language plpgsql security definer as $$
declare
  v_org_id bigint;
  v_invite_role text;
  v_invite_email text;
  v_caller_email text;
begin
  -- 1. Check caller is signed in
  if auth.uid() is null then
    raise exception 'User not signed in';
  end if;

  -- 2. Look up invite by token
  select org_id, role, email, expires_at, accepted_at
  into v_org_id, v_invite_role, v_invite_email, , 
       -- We need to check expiry and acceptance
  from public.invites
  where token = p_token;

  -- 3. Check token exists and not already accepted
  if not found then
    raise exception 'Invalid or unknown token';
  end if;

  if $4 is not null then
    raise exception 'Invite already accepted';
  end if;

  -- 4. Check expiry
  if $3 < now() then
    raise exception 'Invite has expired';
  end if;

  -- 5. Check email match (case-insensitive, verified email from JWT)
  -- Supabase puts verified email in JWT claim `email`
  v_caller_email := normalize_email(coalesce(auth.jwt()->>'email', ''));
  if normalize_email(v_invite_email) != v_caller_email then
    raise exception 'Invite email does not match verified user email';
  end if;

  -- 6. Add user to organization with the invite's role
  insert into public.org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), v_invite_role)
  on conflict (org_id, user_id) do update set role = v_invite_role;

  -- 7. Mark invite as accepted
  update public.invites
  set accepted_at = now()
  where token = p_token;

  return v_org_id;
end;
$$;

