returns boolean
language sql stable
as $$
  select case when exists (
    select 1 from public.polls where id = poll_id and closes_at > now()
  ) then true else false end;
$$;

-- POLLS: Signed-in users can read all polls and options
create policy "R1 Read polls and options" on public.polls
  for select using (auth.role() = 'authenticated');

create policy "R1 Read options" on public.poll_options
  for select using (auth.role() = 'authenticated');

