create policy "R2 User votes" on public.votes
  for select using (user_id = auth.uid());

-- VOTES: Users can insert (vote) once per poll while open, valid option
create policy "R3 Insert vote" on public.votes
  for insert with check (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.polls p
      where p.id = poll_id
      and p.closes_at > now()
    )
    and not exists (
      select 1 from public.votes v
      where v.poll_id = poll_id
      and v.user_id = auth.uid()
    )
  );

-- VOTES: Users can update (change vote) while poll is open and option belongs to poll
create policy "R4 Update/withdraw vote" on public.votes
  for update using (
    auth.role() = 'authenticated'
    and exists (
      select 1 from public.polls p
      where p.id = poll_id
      and p.closes_at > now()
    )
    and option_id in (
      select id from public.poll_options where poll_id = poll_id
    )
  );

-- VOTES: No updates or deletes on closed polls
-- (Handled by the 'p.closes_at > now()' check in R4; no separate delete policy needed as R4's using clause prevents it)

-- POLLS and OPTIONS: No modifications allowed
