create policy "R2_user_votes" on public.votes for select using (user_id = auth.uid());

-- R3: Users can vote once per poll, as themselves, only for an option that belongs to that poll, and only while the poll is open
-- Helper function to validate a vote insert
create or replace function public.validate_vote() returns boolean language sql as $$
  select
    case
      when current_setting('role') = 'service_role' then true
      when auth.uid() is null then false
      -- option must belong to poll
      exists (
        select 1 from public.poll_options opt
        where opt.id = new.option_id
          and opt.poll_id = new.poll_id
      )
      -- poll must be open (closes_at > now())
      and exists (
        select 1 from public.polls p
        where p.id = new.poll_id
          and p.closes_at > now()
      )
      -- user must not already have a vote in this poll
      and not exists (
        select 1 from public.votes v
        where v.poll_id = new.poll_id
          and v.user_id = auth.uid()
      )
    end;
$$;

create policy "R3_insert_votes" on public.votes for insert with check (public.validate_vote());

-- R4: While a poll is open, users can change their vote or withdraw it; votes on closed polls can no longer change
-- Helper function to validate a vote update
create or replace function public.validate_vote_update() returns boolean language sql as $$
  select
    case
      when current_setting('role') = 'service_role' then true
      when auth.uid() is null then false
      -- new option must belong to the poll
      exists (
        select 1 from public.poll_options opt
        where opt.id = new.option_id
          and opt.poll_id = new.poll_id
      )
      -- poll must still be open
      and exists (
        select 1 from public.polls p
        where p.id = new.poll_id
          and p.closes_at > now()
      )
      -- user must be the owner of the existing vote
      and exists (
        select 1 from public.votes v
        where v.poll_id = new.poll_id
          and v.user_id = auth.uid()
      )
    end;
$$;

