    select 1 from public.ops_team
    where user_id = auth.uid()
  );
$$;

-- R5: Anonymous visitors cannot see or change anything
-- Ops team select policy (R2 part: signed-in users can see who is on ops team)
create policy "ops_team_select" on public.ops_team
  for select using (auth.role() = 'authenticated');

-- Requester can see own requests, ops team can see all requests (R1)
