  for select using (
    auth.role() = 'authenticated' and
    (
      requester_id = auth.uid() 
      or exists (select 1 from public.ops_team where user_id = auth.uid())
    )
  );

-- Ops team can see all approvals, requester can see approvals on their own requests (R1)
create policy "approvals_select" on public.access_approvals
  for select using (
    auth.role() = 'authenticated' and
    (
      exists (select 1 from public.access_requests ar where ar.id = access_requests.id and ar.requester_id = auth.uid())
      or exists (select 1 from public.ops_team where user_id = auth.uid())
    )
  );

-- R2: Signed-in users can create requests as themselves; new requests are always pending
-- Requesters can withdraw (delete) their own pending requests
create policy "requests_insert" on public.access_requests
  for insert with check (auth.role() = 'authenticated' and requester_id = auth.uid());

create policy "requests_delete_own_pending" on public.access_requests
  for delete using (
    auth.role() = 'authenticated' 
    and requester_id = auth.uid() 
    and status = 'pending'
  );

-- R3: Nobody can change requests, or create, change or delete approvals, except through approve_access
-- Prevent direct updates/deletes on requests via UI (only via approve_access)
create policy "requests_no_direct_update" on public.access_requests
  for update using (false) with check (false);

create policy "requests_no_direct_delete" on public.access_requests
  for delete using (false);

-- Prevent direct inserts/updates/deletes on approvals via UI
create policy "approvals_no_direct_ops" on public.access_approvals
  for all using (false) with check (false);

-- R4: approve_access function
-- Creates an approval by the caller and, once two different ops team members have approved, sets the request to granted.
create or replace function public.approve_access(p_request_id bigint) returns text language plpgsql security definer as $$
declare
  v_request public.access_requests%rowtype;
  v_approver_id uuid := auth.uid();
  v_ops_count integer;
  v_result text;
begin
  -- Validate request exists and is pending
  select * into v_request from public.access_requests where id = p_request_id;
  if not found then
    raise exception 'Request % does not exist', p_request_id using errortext = 'request_not_found';
  end if;
  if v_request.status != 'pending' then
    raise exception 'Request % is not pending (current status: %)', p_request_id, v_request.status using errortext = 'request_not_pending';
  end if;

  -- Validate caller is on ops team
  if not exists (select 1 from public.ops_team where user_id = v_approver_id) then
    raise exception 'Caller is not an ops team member'; 
  end if;

  -- Validate caller did not make the request
  if v_request.requester_id = v_approver_id then
    raise exception 'Caller cannot approve their own request'; 
  end if;

  -- Validate caller has not already approved this request
  if exists (
    select 1 from public.access_approvals
    where request_id = p_request_id and approver_id = v_approver_id
  ) then
    raise exception 'Caller has already approved this request'; 
  end if;

  -- Insert the approval
  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_approver_id);

  -- Count distinct ops team members who approved
  select count(distinct approver_id) into v_ops_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_ops_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
    v_result := 'granted';
  else
    -- Re-select status (should still be pending)
    select status into v_result from public.access_requests where id = p_request_id;
  end if;

  return v_result;
end;
$$;

-- Grant permissions to authenticated users (covers R1-R5)
grant usage on schema public to authenticated;
grant select on public.ops_team to authenticated;
grant select, insert on public.access_requests to authenticated;
grant select on public.access_approvals to authenticated;
grant execute on function public.approve_access to authenticated;
grant execute on function public.is_ops_member to authenticated;

-- Grant service_role full access (R6)
grant all on public.ops_team to service_role;
grant all on public.access_requests to service_role;
grant all on public.access_approvals to service_role;
grant all on public.access_requests_id_seq to service_role;
grant all on public.access_approvals_id_seq to service_role;
