-- ============================================================
-- POLICIES: Ops team membership & visibility (R1, R2, R3, R4, R6)
-- ============================================================

-- Ops team: members can read their own row; service_role bypasses
create policy "ops_team_members_can_read_own"
  on public.ops_team
  for select
  using ( auth.uid() = user_id );

create policy "service_role_full_ops_team"
  on public.ops_team
  for all
  using ( auth.role() = 'service_role' );

-- Access requests: requesters see own; ops team sees all; anon denied
create policy "requesters_see_own"
  on public.access_requests
  for select
  using ( auth.uid() = requester_id );

create policy "ops_team_see_all_requests"
  on public.access_requests
  for select
  using ( exists ( select 1 from public.ops_team where user_id = auth.uid() ) );

create policy "deny_anon_access_requests"
  on public.access_requests
  for all
  using ( false );

-- Access approvals: requester sees own approvals; ops team sees all; anon denied
create policy "requesters_see_own_approvals"
  on public.access_approvals
  for select
  using ( exists ( select 1 from public.access_requests where id = request_id and requester_id = auth.uid() ) );

create policy "ops_team_see_all_approvals"
  on public.access_approvals
  for select
  using ( exists ( select 1 from public.ops_team where user_id = auth.uid() ) );

create policy "deny_anon_approvals"
  on public.access_approvals
  for all
  using ( false );

-- ============================================================
-- FUNCTION: approve_access (R2-R6)
-- ============================================================

create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
security definer
as $$
declare
  v_request public.access_requests%rowtype;
  v_status text;
  v_approver_count integer;
  v_same_user boolean;
  v_already_approved boolean;
begin
  -- 1. request must exist and be pending
  select * into v_request
  from public.access_requests
  where id = p_request_id;

  if not found then
    raise exception 'Request % does not exist', p_request_id using errcontext;
  end if;

  if v_request.status != 'pending' then
    raise exception 'Request % is not pending (current status: %)', p_request_id, v_request.status using errcontext;
  end if;

  -- 2. caller must be an ops team member
  if not exists ( select 1 from public.ops_team where user_id = auth.uid() ) then
    raise exception 'Caller is not an ops team member';
  end if;

  -- 3. caller must not be the requester
  if auth.uid() = v_request.requester_id then
    raise exception 'Caller cannot approve their own request';
  end if;

  -- 4. caller must not have already approved this request
  select into v_already_approved
    exists ( select 1 from public.access_approvals
             where request_id = p_request_id and approver_id = auth.uid() );
  if v_already_approved then
    raise exception 'Caller has already approved this request';
  end if;

  -- 5. insert the approval
  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, auth.uid(), now());

  -- 6. count distinct approvers; grant if 2 different ops members approved
  select count(distinct approver_id) into v_approver_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_approver_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
  end if;

  -- 7. return current status
  select status into v_status
