-- Enable Row Level Security on all relevant tables
alter table public.ops_team enable row level security;
alter table public.access_requests enable row level security;
alter table public.access_approvals enable row level security;

-- Helper function to check if current user is an ops team member
create or replace function public.is_ops_member() returns boolean language plpgsql as $$
begin
  return exists (select 1 from public.ops_team where user_id = auth.uid());
end;
$$;

-- R5: Anonymous visitors cannot see or change anything
-- ops_team: only authenticated users who are on the ops team can see
create policy "ops_team_select_policy" on public.ops_team
  for select using (auth.role() = 'authenticated' and is_ops_member());

-- access_requests: sign-in users can see all, requesters see their own, ops team sees all
create policy "access_requests_select_policy" on public.access_requests
  for select using (
    auth.role() = 'authenticated' 
    or (auth.role() = 'anon' and false)  -- explicitly deny anon
    or (requester_id = auth.uid())
  );

-- access_approvals: sign-in users can see all, anon denied
create policy "access_approvals_select_policy" on public.access_approvals
  for select using (auth.role() = 'authenticated');

-- R2: Signed-in users can create requests as themselves; new requests are always pending
-- Requesters can withdraw (delete) their own pending requests
create policy "access_requests_insert_policy" on public.access_requests
  for insert with check (auth.role() = 'authenticated' and requester_id = auth.uid());

create policy "access_requests_delete_policy" on public.access_requests
  for delete using (auth.role() = 'authenticated' and requester_id = auth.uid() and status = 'pending');

-- R3: Nobody can change requests, or create, change or delete approvals, except through approve_access
-- These policies effectively block direct DML on approvals and restrictive updates on requests
create policy "no_direct_approval_changes" on public.access_approvals
  for all using (false);

create policy "no_direct_request_changes" on public.access_requests
  for all using (false)
  with check (false);

-- R4: approve_access function handles all approval logic
create or replace function public.approve_access(p_request_id bigint) returns text language plpgsql security definer as $$
declare
  v_request public.access_requests%rowtype;
  v_approver_id uuid := auth.uid();
  v_ops_count integer;
  v_status text;
begin
  -- Validate request exists and is pending
  select * into v_request from public.access_requests where id = p_request_id;
  if not found then
    raise exception 'Request % does not exist', p_request_id using errcode = 'invalid_argument';
  end if;
  if v_request.status != 'pending' then
    raise exception 'Request % is not pending (current status: %)', p_request_id, v_request.status using errcode = 'invalid_argument';
  end if;

  -- Validate caller is on ops team and not the requester
  if not is_ops_member() then
    raise exception 'Caller is not an ops team member';
  end if;
  if v_request.requester_id = v_approver_id then
    raise exception 'Caller cannot approve their own request';
  end if;

  -- Validate caller has not already approved this request
  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_approver_id) then
    raise exception 'Caller has already approved this request';
  end if;

  -- Record the approval
  insert into public.access_approvals (request_id, approver_id) values (p_request_id, v_approver_id);

  -- Check if two different ops team members have approved
  select count(distinct approver_id) into v_ops_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_ops_count >= 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
    v_status := 'granted';
  else
    -- Re-select status after insert (should still be pending)
    select status into v_status from public.access_requests where id = p_request_id;
  end if;

  return v_status;
end;
$$;

-- R1: Signed-in users can see who is on the ops team
-- ops_team select policy already handles this above

-- Grant permissions for service role (server-side code)
grant all on public.ops_team to service_role;
grant all on public.access_requests to service_role;
grant all on public.access_approvals to service_role;
grant usage on function public.approve_access to service_role;
grant usage on function public.is_ops_member to service_role;

-- Grant authenticated users appropriate access
grant select on public.ops_team to authenticated;
grant select, insert, delete on public.access_requests to authenticated;
grant execute on public.approve_access to authenticated;
grant select on public.access_approvals to authenticated;
