-- R4: approve_access RPC handles approval logic.
-- The RPC is defined as a function; policies below allow the service_role (internal call)
-- and restrict direct DML.

-- Create the approve_access function
create or replace function public.approve_access(p_request_id bigint) returns text language plpgsql security definer as $$
declare
  v_request public.access_requests%rowtype;
  v_ops_count integer;
  v_already integer;
  v_caller_uuid uuid := auth.uid();
begin
  -- 1. Request must exist and be pending
  select * into v_request from public.access_requests where id = p_request_id;
  if not found then
    raise exception 'Request % does not exist', p_request_id using errcode = 'invalid_parameter_value';
  end if;
  if v_request.status != 'pending' then
    raise exception 'Request % is not pending (status %)', p_request_id, v_request.status using errcode = 'invalid_operation';
  end if;

  -- 2. Caller must be an ops team member
  if not exists (select 1 from public.ops_team where user_id = v_caller_uuid) then
    raise exception 'Caller is not an ops team member', p_request_id using errcode = 'insufficient_privilege';
  end if;

  -- 3. Caller must not be the requester
  if v_request.requester_id = v_caller_uuid then
    raise exception 'Caller cannot approve their own request', p_request_id using errcode = 'invalid_operation';
  end if;

  -- 4. Caller must not have already approved this request
  select count(*) into v_already from public.access_approvals
  where request_id = p_request_id and approver_id = v_caller_uuid;
  if v_already > 0 then
    raise exception 'Caller has already approved request %', p_request_id using errcode = 'invalid_operation';
  end if;

  -- 5. Insert the approval
  insert into public.access_approvals (request_id, approver_id)
  values (p_request_id, v_caller_uuid);

  -- 6. Check if two different ops members have approved
  select count(distinct approver_id) into v_ops_count
  from public.access_approvals
  where request_id = p_request_id;

  if v_ops_count >= 2 then
    update public.access_requests
    set status = 'granted'
    where id = p_request_id;
  end if;

  return (select status from public.access_requests where id = p_request_id);
end;
$$;

