  for select using (auth.role() = 'authenticated' and exists (select 1 from public.ops_team where user_id = auth.uid()));

create policy "Requesters can create requests" on public.access_requests
  for insert with check (auth.role() = 'authenticated' and requester_id = auth.uid());

create policy "Requesters can withdraw own pending requests" on public.access_requests
  for delete using (requester_id = auth.uid() and status = 'pending');

-- RLS Policies for access_approvals
create policy "Requesters can see approvals on own requests" on public.access_approvals
  for select using (exists (select 1 from public.access_requests where id = request_id and requester_id = auth.uid()));

create policy "Ops team can see all approvals" on public.access_approvals
  for select using (auth.role() = 'authenticated' and exists (select 1 from public.ops_team where user_id = auth.uid()));

-- Deny all other operations on approvals (nobody can insert/update/delete except via RPC)
create policy "Deny all non-RPC operations on approvals" on public.access_approvals
  for all using (false);

-- Create the approve_access function
create or replace function public.approve_access(p_request_id bigint) returns text language plpgsql security definer as $$
declare
  v_request public.access_requests%rowtype;
  v_approver_id uuid := auth.uid();
  v_ops_count integer;
  v_status text;
begin
  -- Validate request exists and is pending
  select * into v_request from public.access_requests where id = p_request_id;
  if not found then
    raise exception 'Request % does not exist', p_request_id using errortype = 'invalid_request';
  end if;
  if v_request.status != 'pending' then
    raise exception 'Request % is not pending (current status: %)', p_request_id, v_request.status using errortype = 'invalid_state';
  end if;

  -- Validate caller is an ops team member
  if not exists (select 1 from public.ops_team where user_id = v_approver_id) then
    raise exception 'Caller is not an ops team member';
  end if;

  -- Validate caller did not make the request
  if v_request.requester_id = v_approver_id then
    raise exception 'Caller cannot approve their own request';
  end if;

  -- Validate caller has not already approved this request
  if exists (select 1 from public.access_approvals where request_id = p_request_id and approver_id = v_approver_id) then
    raise exception 'Caller has already approved this request';
  end if;

  -- Insert the approval
  insert into public.access_approvals (request_id, approver_id) values (p_request_id, v_approver_id);

  -- Check if two different ops team members have approved
  select count(distinct approver_id) into v_approver_id
  from public.access_approvals
  where request_id = p_request_id;

  -- Actually count distinct ops team member approvers
  select count(distinct a.approver_id) into v_approver_id
  from public.access_approvals a
  where a.request_id = p_request_id
    and exists (select 1 from public.ops_team where user_id = a.approver_id);

  if v_approver_id >= 2 then
    update public.access_requests set status = 'granted' where id = p_request_id;
  end if;

  return (select status from public.access_requests where id = p_request_id);
end;
$$;

-- Grant permissions to authenticated users
grant all on public.is_ops_team_member to authenticated;

-- Grant service role full access (implicit via security definer functions)
-- Ensure anon role has no access (already restricted by policies above)
