  for select using (
    provider_id = auth.uid()
  );

-- R3: Patient can book an open future slot for themselves
create function public.handle_slot_book()
  returns trigger as $$
begin
  -- Only allow booking if slot is open and in the future
  if new.booked_by is not null then
    -- If already booked, only allow if booking is for the same user and slot is future
    if new.booked_by != auth.uid() then
      return new;
    end if;
  end if;
  if (new.booked_by is null) then
    if (starts_at <= now()) then
      return new;
    end if;
    -- Check slot is not already booked by someone else
    if exists (select 1 from public.slots s2 where s2.id = new.id and s2.booked_by is not null and s2.booked_by != auth.uid()) then
      return new;
    end if;
  end if;
  new.booked_by := auth.uid();
  return new;
end;
$$ language plpgsql security definer;

create trigger on public.slots
  after update
  for each row
  when (old.booked_by is distinct from new.booked_by)
  execute function public.handle_slot_book();

