  for update using (
    exists (
      select 1 from public.project_members
      where project_id = issues.project_id
        and user_id = auth.uid()
        and role in ('developer', 'maintainer')
    )
    and (
      -- allow updating non-confidential fields
      (not is_confidential) or
      -- allow maintainer to toggle confidential
      (auth.role() = 'service_role' or exists (
        select 1 from public.project_members
        where project_id = issues.project_id
          and user_id = auth.uid()
          and role = 'maintainer'
      ))
    )
