    raise exception 'No refills left';
  end if;

  -- Check if the caller is the prescription owner
  if current_setting('request.jwt.claim.sub')::uuid = v_owner_id then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

