  for select using (true);

-- R1: prescriptions view
-- patients see their own; pharmacists see all
create policy "prescriptions_view" on public.prescriptions
  for select using (
    auth.role() = 'authenticated' and
    (
      patient_id = auth.uid() or
      exists (select 1 from public.pharmacists where user_id = auth.uid())
    )
  );

-- R1: dispenses view
-- patients see dispenses of their own prescriptions; pharmacists see all
create policy "dispenses_view" on public.dispenses
  for select using (
    auth.role() = 'authenticated' and
    (
      exists (select 1 from public.prescriptions where id = prescription_id and patient_id = auth.uid()) or
      exists (select 1 from public.pharmacists where user_id = auth.uid())
    )
  );

-- R2: block direct DML on prescriptions and dispenses
create policy "no_dml_prescriptions" on public.prescriptions
  for all using (false);

create policy "no_dml_dispenses" on public.dispenses
  for all using (false);

-- R3+R4: dispense function
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
as $$
declare
  v_pharmacist_id uuid;
  v_refills_left integer;
  v_prescription patient_row%rowtype;
begin
  -- R6: service role bypasses RLS, but we check internally
  if auth.role() = 'service_role' then
    -- server-side: full access, just perform the operation
    update public.prescriptions
    set refills_left = greatest(refills_left - 1, 0),
        dispensed_at = now()
    where id = p_prescription_id
    returning refills_left into v_refills_left;

    insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
    values (p_prescription_id, current_setting('app.current_pharmacist_id')::uuid, now());

    return v_refills_left;
  end if;

  -- R3+R4: signed-in user checks
  -- caller must be a pharmacist
  select user_id into v_pharmacist_id
  from public.pharmacists
  where user_id = auth.uid();

  if v_pharmacist_id is null then
    raise exception 'caller is not a pharmacist';
  end if;

  -- prescription must exist
  select * into v_prescription
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'prescription does not exist';
  end if;

  -- R4: cannot dispense own prescription (if patient is also a pharmacist? rule says "own")
  if v_prescription.patient_id = auth.uid() then
    raise exception 'cannot dispense own prescription';
  end if;

  -- R4: expired
  if v_prescription.expires_at < now() then
    raise exception 'prescription has expired';
  end if;

  -- R4: no refills left
  if v_prescription.refills_left <= 0 then
    raise exception 'no refills left';
  end if;

  -- perform the dispense
  update public.prescriptions
  set refills_left = refills_left - 1,
      dispensed_at = now()
  where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  return (select refills_left from public.prescriptions where id = p_prescription_id);
end;
$$;

-- R5: anonymous visitors cannot see or change anything
-- policies already restrict to authenticated; anon has no access by default
-- explicit deny for anon on tables
create policy "anon_no_access" on public.pharmacists
  for all using (false);

create policy "anon_no_access_prescriptions" on public.prescriptions
  for all using (false);

create policy "anon_no_access_dispenses" on public.dispenses
  for all using (false);

-- grants: service role keeps full access (already implicit, but explicit)
grant all on public.pharmacists to service_role;
grant all on public.prescriptions to service_role;
grant all on public.dispenses to service_role;

-- authenticated users get select per policies
grant select on public.pharmacists to authenticated;
grant select on public.prescriptions to authenticated;
grant select on public.dispenses to authenticated;
