-- Enable RLS on all relevant tables
alter table public.pharmacists enable row level security;
alter table public.prescriptions enable row level security;
alter table public.dispenses enable row level security;

-- Helper function to check if current user is a pharmacist
create or replace function public.is_pharmacist() returns boolean language sql as $$
  select exists (
    select 1 from public.pharmacists
    where user_id = auth.uid()
  );
$$;

-- Policy: Signed-in users can see pharmacists (R1)
create policy "Users can see pharmacists" on public.pharmacists
  for select using ( auth.role() = 'authenticated' );

-- Policy: Patients can see their own prescriptions (R1)
create policy "Patients can see own prescriptions" on public.prescriptions
  for select using ( auth.uid() = patient_id );

-- Policy: Pharmacists can see every prescription (R1)
create policy "Pharmacists can see all prescriptions" on public.prescriptions
  for select using ( public.is_pharmacist() );

-- Policy: Pharmacists can see every dispense (R1)
create policy "Pharmacists can see all dispenses" on public.dispenses
  for select using ( public.is_pharmacist() );

-- Policy: Patients can see dispenses of their own prescriptions (R1)
create policy "Patients can see own dispenses" on public.dispenses
  for select using (
    exists (
      select 1 from public.prescriptions
      where id = dispenses.prescription_id
      and patient_id = auth.uid()
    )
  );

-- R2: Block all insert/update/delete on prescriptions and dispenses
create policy "Block DML on prescriptions" on public.prescriptions
  for all using ( false );

create policy "Block DML on dispenses" on public.dispenses
  for all using ( false );

-- R3 + R4: dispense function
-- Returns refills left after dispensing, or raises error if conditions not met
create or replace function public.dispense(p_prescription_id bigint)
returns integer language plpgsql security invoker as $$
declare
  v_pharmacist uuid;
  v_patient uuid;
  v_refills integer;
  v_expires timestamptz;
  v_own_prescription boolean;
begin
  -- R4: Caller must be a pharmacist
  if not public.is_pharmacist() then
    raise exception 'Only pharmacists can dispense';
  end if;

  -- R4: Prescription must exist
  select patient_id, refills_left, expires_at, user_id
  into v_patient, v_refills, v_expires, v_pharmacist
  from public.prescriptions
  where id = p_prescription_id;

  if not found then
    raise exception 'Prescription not found';
  end if;

  -- R4: Prescription must not be expired
  if now() > v_expires then
    raise exception 'Prescription has expired';
  end if;

  -- R4: Prescription must have refills left
  if v_refills <= 0 then
    raise exception 'No refills left';
  end if;

  -- R4: Caller cannot dispense their own prescription
  if auth.uid() = v_patient then
    raise exception 'Pharmacists cannot dispense their own prescriptions';
  end if;

  -- Decrement refills
  update public.prescriptions
  set refills_left = v_refills - 1
  where id = p_prescription_id;

  -- Record the dispense
  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, auth.uid(), now());

  -- Return remaining refills
  return v_refills - 1;
end;
$$;

-- R5: Anonymous visitors cannot see or change anything
-- (RLS on tables already prevents access for anon unless explicitly allowed;
--  the policies above only allow authenticated or pharmacist access,
--  and service_role bypasses RLS per Supabase behavior.)

-- R6: Server-side code using service role keeps full access
-- (No additional grant needed; service_role bypasses RLS by default.)
