-- Enable RLS on tables
alter table public.documents enable row level security;
alter table public.doc_access enable row level security;

-- Helper function: check if user has edit access to a document
create or replace function public.has_edit_access(p_doc_id bigint, p_user_id uuid)
returns boolean language sql strict as $$
  select exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id
      and user_id = p_user_id
      and can_edit = true
  );
$$;

-- Helper function: check if user has any access to a document
create or replace function public.has_any_access(p_doc_id bigint, p_user_id uuid)
returns boolean language sql strict as $$
  select exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id
      and user_id = p_user_id
  );
$$;

-- Policy: readers can read documents they have access to
create policy "documents_read_policy" on public.documents
for select using (
  auth.role() = 'anon' false
  or exists (
    select 1 from public.doc_access
    where doc_id = id
      and user_id = auth.uid()
  )
);

-- Policy: doc_access is not directly manipulable; lock it down
create policy "doc_access_no_op" on public.doc_access
for all using (false) with check (false);

-- Policy: users can read their own access rows (for completeness)
create policy "doc_access_self_read" on public.doc_access
for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Functions: checkout_document / checkin_document
-- ---------------------------------------------------------------------------

create or replace function public.checkout_document(p_doc_id bigint)
returns void language plpgsql strict as $$
declare
  v_user uuid := auth.uid();
  v_has_edit boolean;
  v_checked_out_by uuid;
begin
  -- 1. Document must exist
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document % does not exist', p_doc_id using errcontext;
  end if;

  -- 2. User must have edit access
  select has_edit_access(p_doc_id, v_user) into v_has_edit;
  if not v_has_edit then
    raise exception 'User % has no edit access to document %', v_user, p_doc_id using errcontext;
  end if;

  -- 3. If already checked out by this user, succeed (no-op)
  select checked_out_by into v_checked_out_by from public.documents where id = p_doc_id;
  if v_checked_out_by = v_user then
    return;
  end if;

  -- 4. If someone else has it checked out, fail
  if v_checked_out_by is not null and v_checked_out_by != v_user then
    raise exception 'Document % is already checked out by %', p_doc_id, v_checked_out_by using errcontext;
  end if;

  -- 5. Lock the document for the user
  update public.documents set checked_out_by = v_user where id = p_doc_id;
end;
$$;

create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void language plpgsql strict as $$
declare
  v_user uuid := auth.uid();
  v_checked_out_by uuid;
begin
  -- 1. Document must exist
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document % does not exist', p_doc_id using errcontext;
  end if;

  -- 2. Must be currently checked out by this user
  select checked_out_by into v_checked_out_by from public.documents where id = p_doc_id;
  if v_checked_out_by is null or v_checked_out_by != v_user then
    raise exception 'Document % is not checked out by user %', p_doc_id, v_user using errcontext;
  end if;

  -- 3. Update body and release lock
  update public.documents set body = p_body, checked_out_by = null where id = p_doc_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Grant service_role full access (bypasses RLS automatically)
-- ---------------------------------------------------------------------------

grant all on public.documents to service_role;
grant all on public.doc_access to service_role;
grant all on public.checkout_document to service_role;
grant all on public.checkin_document to service_role;

-- Ensure anon role has no access (RLS policies above already restrict)
revoke all on public.documents from anon;
revoke all on public.doc_access from anon;
revoke all on public.checkout_document from anon;
revoke all on public.checkin_document from anon;
