        select 1 from public.orgs o where o.id = org_id and o.require_sso
      )
      or
      exists (
        select 1 from jsonb_array_elements(auth.jwt()->'amr') as amr_entry
        where (amr_entry->>'method')::text = 'sso/saml'
      )
    )
  );

-- R4: Only amr claim counts as proof of SSO; nobody can change memberships
-- No policies for inserting/updating org_members - memberships are managed server-side
-- The absence of insert/update policies on org_members effectively prevents
-- membership changes through the app from anon/non-admin sessions

-- R6: Server-side code using service_role keeps full access
-- (RLS is enabled but service_role bypasses it by default in Supabase)
