-- Enable RLS on tables
alter table public.documents enable row level security;
alter table public.doc_access enable row level security;

-- Helper function: check if user has edit access on a document
create or replace function public.has_edit_access(p_doc_id bigint) returns boolean as $$
begin
  return exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id and user_id = auth.uid() and can_edit = true
  );
end;
$$ language plpgsql security definer;

-- Policy: anon sees nothing
create policy "anon_no_access" on public.documents for all to anon using (false) with check (false);
create policy "anon_no_access_doc_access" on public.doc_access for all to anon using (false) with check (false);

-- Policy: authenticated users can read their access rows
create policy "auth_read_access" on public.doc_access for select to authenticated using (user_id = auth.uid());
create policy "auth_read_documents" on public.documents for select to authenticated using (
  exists (select 1 from public.doc_access where doc_id = id and user_id = auth.uid())
);

-- Policy: authenticated users can read documents they have access to (including read-only)
create policy "auth_read_any_access" on public.documents for select to authenticated using (
  exists (select 1 from public.doc_access where doc_id = id)
);

-- Functions: checkout_document and checkin_document
create or replace function public.checkout_document(p_doc_id bigint) returns void as $$
declare
  v_checker uuid;
  v_already_checker uuid;
  v_has_access boolean;
begin
  -- Document must exist
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document not found';
  end if;

  -- Check edit access
  if not public.has_edit_access(p_doc_id) then
    raise exception 'User does not have edit access to this document';
  end if;

  -- If already checked out by this user, succeed (no-op)
  if (select checked_out_by from public.documents where id = p_doc_id) = auth.uid() then
    return;
  end if;

  -- If someone else has it checked out, fail
  if exists (select 1 from public.documents where id = p_doc_id and checked_out_by is not null and checked_out_by != auth.uid()) then
    raise exception 'Document is already checked out by another user';
  end if;

  -- Lock the document for the caller
  update public.documents set checked_out_by = auth.uid() where id = p_doc_id;
end;
$$ language plpgsql security definer;

create or replace function public.checkin_document(p_doc_id bigint, p_body text) returns void as $$
declare
  v_current_checker uuid;
begin
  -- Document must exist
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document not found';
  end if;

  -- The caller must currently have it checked out
  select checked_out_by into v_current_checker from public.documents where id = p_doc_id;
  if v_current_checker is null or v_current_checker != auth.uid() then
    raise exception 'You do not currently have this document checked out';
  end if;

  -- Update body and release lock
  update public.documents set body = p_body, checked_out_by = null where id = p_doc_id;
end;
$$ language plpgsql security definer;

-- Grant service_role full access (bypasses RLS)
grant all on public.documents to service_role;
grant all on public.doc_access to service_role;
grant all on public.checkout_document to service_role;
grant all on public.checkin_document to service_role;

-- Revoke public access to functions (enforces RLS)
revoke all on public.checkout_document from public;
revoke all on public.checkin_document from public;
