-- Function: checkout_document
-- Locks a document for the caller. Succeeds if user already holds the lock or has edit access.
create or replace function public.checkout_document(p_doc_id bigint)
returns void language plpgsql strict as $$
declare
  v_user_id uuid := auth.uid();
  v_already_checked_out boolean;
  v_has_access boolean;
  v_exists boolean;
begin
  -- Check if document exists
  select exists(select 1 from public.documents where id = p_doc_id) into v_exists;
  if not v_exists then
    raise exception 'Document with id % does not exist', p_doc_id using errcode = 'invalid_parameter_value';
    return;
  end if;

  -- Check if user already has it checked out (success case)
  select checked_out_by = v_user_id into v_already_checked_out
  from public.documents
  where id = p_doc_id;

  if v_already_checked_out then
    -- Already checked out by this user; succeed silently
    return;
  end if;

  -- Check if user has edit access
  select has_edit_access(p_doc_id, v_user_id) into v_has_access;
  if not v_has_access then
    raise exception 'User has no edit access to document', using errcode = 'insufficient_privilege';
    return;
  end if;

  -- Check if someone else has it checked out
  if exists(select 1 from public.documents where id = p_doc_id and checked_out_by is not null and checked_out_by != v_user_id) then
    raise exception 'Document is already checked out by another user', using errcode = 'invalid_parameter_value';
    return;
  end if;

  -- Apply the lock
  update public.documents set checked_out_by = v_user_id where id = p_doc_id;
end;
$$;

-- Function: checkin_document
-- Saves new body and releases the lock. Only succeeds if caller currently has it checked out.
create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void language plpgsql strict as $$
declare
  v_user_id uuid := auth.uid();
  v_current_checker uuid;
begin
  -- Check if document exists
  if not exists(select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document with id % does not exist', p_doc_id using errcode = 'invalid_parameter_value';
    return;
  end if;

  -- Check if caller currently has it checked out
  select checked_out_by into v_current_checker
  from public.documents
  where id = p_doc_id;

  if v_current_checker is null or v_current_checker != v_user_id then
    raise exception 'User does not currently have the document checked out', using errcode = 'invalid_parameter_value';
    return;
  end if;

  -- Update body and release lock in one atomic operation
  update public.documents
  set body = p_body, checked_out_by = null
  where id = p_doc_id;
end;
$$;

