grant all on public.doc_access to service_role;
grant all on public.checkout_document to service_role;
grant all on public.checkin_document to service_role;

-- Grant authenticated users read access (needed for policies to evaluate)
grant select on public.documents to authenticated;
grant select on public.doc_access to authenticated;
