declare
  v_user_id uuid := auth.uid();
  v_current_checkout uuid;
begin
  -- Check document exists
  if not exists (select 1 from public.documents where id = p_doc_id) then
    raise exception 'Document does not exist';
  end if;

  -- Check if already checked out by someone else
  select checked_out_by into v_current_checkout from public.documents where id = p_doc_id;
  if v_current_checkout is not null and v_current_checkout != v_user_id then
    raise exception 'Document is already checked out by another user';
  end if;

  -- Check edit access
  if not public.has_edit_access(p_doc_id, v_user_id) then
    raise exception 'You do not have edit access to this document';
  end if;

  -- Update checked_out_by (checking out you already holds is idempotent)
  update public.documents set checked_out_by = v_user_id where id = p_doc_id;
end;
$$;

