alter table public.pastes enable row level security;

-- R1: Anyone can read public (non-private, non-expired) pastes
create policy "Anyone can read public pastes" on public.pastes
for select using ((not is_private) and (expires_at is null or expires_at > now()));

-- R2: Signed-in authors can read their own private and expired pastes
create policy "Authors can read own pastes" on public.pastes
for select using (auth.uid() = author_id);

-- R3: Anyone can create pastes; anonymous pastes cannot be private
create policy "Anyone can create pastes" on public.pastes
for insert with check ((not is_private) or (auth.role() = 'authenticated'));

-- R4: Authors can delete their own pastes; no updates allowed
create policy "Authors can delete own pastes" on public.pastes
for delete using (auth.uid() = author_id);

-- R4: Prevent any updates to pastes
create policy "No updates allowed" on public.pastes
for update using (false);

-- R4: Anonymous pastes (author_id is null) can only be removed by server-side code
-- This is enforced by the delete policy above combined with the author_id default

-- R5: Grant service_role full access (already has bypass by default, but explicit grant ensures clarity)
grant all on public.pastes to service_role;

-- Helper function to safely insert a paste (optional, can be used by client code)
create or replace function public.create_paste(content text, is_private boolean, expires_at timestamptz)
returns void language sql security invoker as $$
begin
  insert into public.pastes (content, is_private, expires_at)
  values (content, is_private, expires_at);
end;$$;

-- Grant execute on the helper function to authenticated users
grant execute on function public.create_paste to authenticated;
