-- Enable RLS on the pastes table
alter table public.pastes enable row level security;

-- Allow anyone to read non-private, non-expired pastes
create policy "Anyone can read active pastes"
  on public.pastes
  for select
  using ((not is_private) and (expires_at is null or expires_at > now()));

-- Allow signed-in authors to read their own private/expired pastes
