  on public.pastes
  for insert
  with check (true);

-- Allow authors to delete their own pastes
create policy "Authors can delete own pastes"
  on public.pastes
  for delete
  using (author_id = auth.uid());

-- Create a function to restrict deletion of anonymous pastes
-- This ensures anonymous pastes (author_id is null) can only be removed by service_role
create or replace function public.restrict_anonymous_delete()
returns trigger as $$
begin
  -- If the paste has no author (anonymous), prevent deletion via non-service roles
  if (TG_OP = 'DELETE') and (coalesce(old.author_id, '00000000-0000-0000-0000-000000000000') is null) then
    if (auth.role() != 'service_role') then
      signal sqlstate '42501' using message = 'Anonymous pastes can only be removed by server-side code';
    end if;
  end if;
  return null;
end;
$$ language plpgsql security definer;

-- Attach the trigger to catch deletions
create trigger restrict_anonymous_delete_trigger
  after delete on public.pastes
  for each row
  execute function public.restrict_anonymous_delete();

-- Grant necessary permissions to authenticated role
grant all on public.pastes to authenticated;
grant usage, select on function public.restrict_anonymous_delete to authenticated;
