```sql
-- Enable Row Level Security on both tables
alter table public.documents enable row level security;
alter table public.doc_access enable row level security;

-- Helper function to check if user has edit access on a document
create or replace function public.has_edit_access(p_doc_id bigint) returns boolean language sql security definer as $$
  select exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id
    and user_id = auth.uid()
    and can_edit = true
  );
$$;

-- Helper function to check if user has any access to a document
create or replace function public.has_access(p_doc_id bigint) returns boolean language sql security definer as $$
  select exists (
    select 1 from public.doc_access
    where doc_id = p_doc_id
    and user_id = auth.uid()
  );
$$;

-- Helper function to check if a document is currently checked out
create or replace function public.is_checked_out(p_doc_id bigint) returns boolean language sql security definer as $$
  select checked_out_by is not null
  from public.documents
  where id = p_doc_id;
$$;

-- RLS Policies for public.documents
create policy "Users can read documents they have access to" on public.documents
  for select using (public.has_access(id));

create policy "Service role has full access on documents" on public.documents
  using (auth.role() = 'service_role');

-- RLS Policies for public.doc_access
-- Allow authenticated users to read their own access rows
create policy "Users can read own access rows" on public.doc_access
  for select using (user_id = auth.uid());

-- Service role has full access to doc_access
create policy "Service role has full access on doc_access" on public.doc_access
  using (auth.role() = 'service_role');

-- Checkout document function
create or replace function public.checkout_document(p_doc_id bigint) returns void language plpgsql security definer as $$
declare
  v_checker boolean;
  v_already boolean;
  v_checker_id uuid;
begin
  -- Check if document exists
  if not public.has_access(p_doc_id) then
    raise exception 'Document does not exist or you do not have access';
  end if;

  -- Check if user already has it checked out
  select checked_out_by, public.is_checked_out(p_doc_id) into v_checker_id, v_checker
  from public.documents
  where id = p_doc_id;

  if v_checker then
    if v_checker_id = auth.uid() then
      -- Already checked out by this user, success (no-op)
      return;
    else
      raise exception 'Document is already checked out by another user';
    end if;
  end if;

  -- Check edit access
  if not public.has_edit_access(p_doc_id) then
    raise exception 'You do not have edit access to this document';
  end if;

  -- Lock the document
  update public.documents
  set checked_out_by = auth.uid()
  where id = p_doc_id;
end;
$$;

-- Checkin document function
create or replace function public.checkin_document(p_doc_id bigint, p_body text) returns void language plpgsql security definer as $$
declare
  v_checker_id uuid;
  v_checker boolean;
begin
  -- Check if document exists and is checked out by this user
  select checked_out_by, public.is_checked_out(p_doc_id) into v_checker_id, v_checker
  from public.documents
  where id = p_doc_id;

  if not v_checker then
    raise exception 'Document is not currently checked out';
  end if;

  if v_checker_id != auth.uid() then
    raise exception 'You do not have this document checked out';
  end if;

  -- Update body and release lock
  update public.documents
  set body = p_body,
      checked_out_by = null
  where id = p_doc_id;
end;
$$;

-- Grant necessary permissions
grant usage on schema public to authenticated;
grant execute on function public.checkout_document to authenticated;
grant execute on function public.checkin_document to authenticated;

-- Revoke direct table access to prevent bypassing functions
revoke all on public.documents from public;
revoke all on public.doc_access from public;
grant select on public.documents to authenticated using (public.has_access(id));
grant select on public.doc_access to authenticated using (user_id = auth.uid());
```

