  for insert with check (
    public.is_building_staff() or
    exists(select 1 from public.requests r where r.id = request_id and public.is_resident_of(r.unit_id))
  );

-- Grant service_role full access (already implicit, but explicit for clarity)
grant all on public.units to service_role;
grant all on public.residents to service_role;
grant all on public.building_staff to service_role;
grant all on public.requests to service_role;
grant all on public.request_photos to service_role;

-- Revoke public access (ensure anon cannot see/change anything)
revoke all on public.units from public;
revoke all on public.residents from public;
revoke all on public.building_staff from public;
revoke all on public.requests from public;
revoke all on public.request_photos from public;
