alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

-- Helper function: get current user's building IDs based on their role
create function public.get_user_building_ids() returns setof bigint language sql stable security definer as $$
  select building_id from public.building_staff where user_id = current_setting('app.current_user_id')::uuid;
$$;

-- Helper function: check if user is a resident of a specific unit
create function public.is_resident_of_unit(user_id uuid, unit_id bigint) returns boolean language sql stable security definer as $$
  select exists (
    select 1 from public.residents where user_id = user_id and unit_id = unit_id
  );
$$;

-- Policy: R1 - Visibility for units and requests/photos
-- Residents see their own units and related requests/photos
-- Staff see all units/buildings they are assigned to
create policy "residents_see_own_units" on public.units
  for select using (public.is_resident_of_unit(auth.uid(), id));

create policy "staff_see_units_in_buildings" on public.units
  for select using (exists (select 1 from public.building_staff where building_staff.user_id = auth.uid()));

-- Residents see their own requests and photos
create policy "residents_see_own_requests" on public.requests
  for select using (
    exists (select 1 from public.residents where user_id = auth.uid() and unit_id = requests.unit_id)
  );

-- Staff see all requests in their buildings
create policy "staff_see_all_requests" on public.requests
  for select using (
    exists (select 1 from public.building_staff where building_staff.building_id = 
      (select building_id from public.units where id = requests.unit_id) and building_staff.user_id = auth.uid())
  );

-- Photos visibility follows the same rules as their parent requests
create policy "residents_see_own_photos" on public.request_photos
  for select using (
    exists (select 1 from public.residents where user_id = auth.uid() and 
      unit_id = (select unit_id from public.requests where id = request_photos.request_id))
  );

create policy "staff_see_all_photos" on public.request_photos
  for select using (
    exists (select 1 from public.building_staff where building_staff.building_id = 
      (select building_id from public.units where id = 
        (select unit_id from public.requests where id = request_photos.request_id)) and 
      building_staff.user_id = auth.uid())
  );

-- Policy: R2 - Residents can create requests for their own units
create policy "residents_create_requests" on public.requests
  for insert with check (
    exists (select 1 from public.residents where user_id = auth.uid() and unit_id = new.unit_id)
    and auth.uid() = new.created_by
  );

-- Policy: R3 - Residents and staff can add photos to visible requests
create policy "residents_add_photos" on public.request_photos
  for insert with check (
    exists (select 1 from public.residents where user_id = auth.uid() and 
      unit_id = (select unit_id from public.requests where id = request_id))
  );

create policy "staff_add_photos" on public.request_photos
  for insert with check (
    exists (select 1 from public.building_staff where building_staff.user_id = auth.uid())
  );

-- Policy: R4 - Staff can change status, nobody else can change anything else
create policy "staff_update_status" on public.requests
  for update using (
    exists (select 1 from public.building_staff where building_staff.user_id = auth.uid())
  )
  with check (
    -- Only status column can be updated, and only to valid values
    case when TG_OP = 'UPDATE' then (new.status = any(array['open', 'in_progress', 'done'])) else true end)
    and exists (select 1 from public.building_staff where building_staff.user_id = auth.uid())
  );

-- Explicitly prevent residents from updating status
create policy "residents_no_status_update" on public.requests
  for update using (false);

-- Policy: R5 - Users can see their own residence and staff rows; no modifications
create policy "users_see_own_residence" on public.residents
  for select using (user_id = auth.uid());

create policy "users_see_own_staff" on public.building_staff
  for select using (user_id = auth.uid());

-- Prevent any updates/deletes on units, residents, staff through the app
create policy "no_modifications_units" on public.units
  for all using (false);

create policy "no_modifications_residents" on public.residents
  for all using (false);

create policy "no_modifications_building_staff" on public.building_staff
  for all using (false);

-- Policy: R6 - Anonymous visitors cannot see or change anything
-- The existing policies already restrict to auth.uid(), but we add explicit denial for anon role
create policy "deny_anonymous_access" on public.units
  for all using (auth.role() != 'anon');

create policy "deny_anonymous_requests" on public.requests
  for all using (auth.role() != 'anon');

create policy "deny_anonymous_photos" on public.request_photos
  for all using (auth.role() != 'anon');

create policy "deny_anonymous_residents" on public.residents
  for all using (auth.role() != 'anon');

create policy "deny_anonymous_building_staff" on public.building_staff
  for all using (auth.role() != 'anon');

-- Policy: R7 - Server-side code using service role keeps full access
-- We create a policy that allows service_role bypass
create policy "service_role_full_access" on public.units
  for all using (auth.role() = 'service_role');

create policy "service_role_full_access_requests" on public.requests
  for all using (auth.role() = 'service_role');

create policy "service_role_full_access_photos" on public.request_photos
  for all using (auth.role() = 'service_role');

create policy "service_role_full_access_residents" on public.residents
  for all using (auth.role() = 'service_role');

create policy "service_role_full_access_building_staff" on public.building_staff
  for all using (auth.role() = 'service_role');

-- Grant usage on the helper functions to authenticated users
grant usage on function public.get_user_building_ids() to authenticated;
grant usage on function public.is_resident_of_unit(user_id bigint, unit_id bigint) to authenticated;
