create policy "Finders can insert items" on public.items for insert with check (auth.role() = 'authenticated' and found_by = auth.uid());
create policy "Finders can update own items" on public.items for update using (found_by = auth.uid()) with check (found_by = auth.uid());

-- R2: Claimants see own claims; Finders see claims on their items
create policy "Claimants see own claims" on public.claims for select using (claimant_id = auth.uid());
create policy "Finders see claims on their items" on public.claims for select using (item_id in (select id from public.items where found_by = auth.uid()));

-- R3: Users can claim open items they did not find (as themselves, pending)
create policy "Anyone can claim open items" on public.claims for insert with check (
  auth.role() = 'authenticated' 
  and status = 'pending' 
  and item_id in (select id from public.items where status = 'open' and found_by != auth.uid())
);

-- R4: Only finder can approve/reject pending claim; one approved claim per item; immutable otherwise
create policy "Finders can approve/reject claims" on public.claims for update using (
  auth.role() = 'authenticated' 
  and exists (select 1 from public.items where id = item_id and found_by = auth.uid())
) with check (
  -- Status change only allowed by finder, and only to approved/rejected from pending
  status in ('approved', 'rejected') 
  and old.status = 'pending'
  and not exists (select 1 from public.claims where item_id = item_id and status = 'approved' and id != id)
);

-- R5: Anonymous visitors cannot see or change anything
-- (Deny all for anon role by default since auth.role() IS NOT NULL for signed-in users)
-- Supabase anon bypasses RLS if no policy matches; we explicitly deny anon access via policies that exclude them.
create policy "Deny anon access to items" on public.items for all using (auth.role() != 'anon');
create policy "Deny anon access to claims" on public.claims for all using (auth.role() != 'anon');

