    and (
      -- New status must be approved or rejected, and only finder can set it
      (status in ('approved', 'rejected') and auth.uid() = (select found_by from public.items where id = item_id))
      or
      -- Or leaving status unchanged is allowed for finder
      (status = (select status from public.claims where id = claims.id))
    )
  );

