  for select using (auth.role() = 'authenticated');

create policy "listings_select_anonymous_deny" on public.listings
  for select using (false);

-- RLS Policies for orders
-- R1: Buyers and sellers can see orders they are part of
create policy "orders_select_by_party" on public.orders
  for select using (
    auth.role() = 'authenticated' 
    and (buyer_id = auth.uid() or seller_id = auth.uid())
  );

create policy "orders_select_anonymous_deny" on public.orders
  for select using (false);

-- R2: Buyers can place orders (enforced via check constraint + insert policy)
-- New orders must have seller_id matching the listing's seller and amount matching the listing's price
-- Buyers cannot buy their own listing
create policy "orders_insert_buyer_cannot_sell_own" on public.orders
  for insert with check (
    auth.role() = 'authenticated'
    and listing_id in (
      select id from public.listings where seller_id != auth.uid()
    )
    and amount = (
      select price from public.listings where id = listing_id
    )
  );

-- Helper function to check if current user is the order's seller
create or replace function public.is_order_seller(p_order_id bigint)
returns boolean
language sql stable security invoker
as $$
  select case when exists (
    select 1 from public.orders where id = p_order_id and seller_id = auth.uid()
  ) then true else false end;
$$;

-- Helper function to check if current user is the order's buyer
create or replace function public.is_order_buyer(p_order_id bigint)
returns boolean
language sql stable security invoker
as $$
  select case when exists (
    select 1 from public.orders where id = p_order_id and buyer_id = auth.uid()
  ) then true else false end;
$$;

-- Public functions for status transitions
-- R3, R4, R5: Only callable via service role from server-side code; app calls these functions
create or replace function public.mark_shipped(p_order_id bigint)
returns text
language plpgsql stable security definer
as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- R5: Order must exist
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order not found';
  end if;

  -- R5: Must be in 'paid' status
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if v_status != 'paid' then
    raise exception 'Order is not in pending_payment status';
  end if;

  -- R4: Only the seller can call mark_shipped
  if auth.role() != 'service_role' and auth.uid() != v_seller_id then
    raise exception 'Only the seller can mark an order as shipped';
  end if;

  -- Update status
  update public.orders
  set status = 'shipped'
  where id = p_order_id;

  return 'shipped';
end;
$$;

create or replace function public.release_funds(p_order_id bigint)
returns text
language plpgsql stable security definer
as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- R5: Order must exist
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order not found';
  end if;

  -- R5: Must be in 'shipped' status
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if v_status != 'shipped' then
    raise exception 'Order is not in shipped status';
  end if;

  -- R4: Only the buyer can call release_funds
  if auth.role() != 'service_role' and auth.uid() != v_buyer_id then
    raise exception 'Only the buyer can release funds';
  end if;

  -- Update status
  update public.orders
  set status = 'released'
  where id = p_order_id;

  return 'released';
end;
$$;

create or replace function public.refund_order(p_order_id bigint)
returns text
language plpgsql stable security definer
as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- R5: Order must exist
  if not exists (select 1 from public.orders where id = p_order_id) then
    raise exception 'Order not found';
  end if;

  -- R5: Must be in 'paid' or 'shipped' status
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if not (v_status = 'paid' or v_status = 'shipped') then
    raise exception 'Order is not in an allowed status for refund';
  end if;

  -- R4: Only the seller can call refund_order
  if auth.role() != 'service_role' and auth.uid() != v_seller_id then
    raise exception 'Only the seller can refund an order';
  end if;

  -- Update status
  update public.orders
  set status = 'refunded'
  where id = p_order_id;

  return 'refunded';
end;
$$;

