-- Function: mark_shipped - seller moves order from paid to shipped (R4, R5)
create or replace function public.mark_shipped(p_order_id bigint)
returns text language plpgsql security definer as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- Check order exists
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order with ID % not found', p_order_id using errortext = 'Order not found';
  end if;

  -- Check caller is the seller
  if auth.role() != 'service_role' and v_seller_id != auth.uid() then
    raise exception 'Only the seller can mark order shipped';
  end if;

  -- Check allowed status transition: paid -> shipped
  if v_status != 'paid' then
    raise exception 'Order is not in paid status, current status: %', v_status;
  end if;

  -- Update status
  update public.orders
  set status = 'shipped'
  where id = p_order_id;

  return 'shipped';
end;
$$;

-- Function: release_funds - buyer moves order from shipped to released (R4, R5)
create or replace function public.release_funds(p_order_id bigint)
returns text language plpgsql security definer as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- Check order exists
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order with ID % not found', p_order_id using errortext = 'Order not found';
  end if;

  -- Check caller is the buyer
  if auth.role() != 'service_role' and v_buyer_id != auth.uid() then
    raise exception 'Only the buyer can release funds';
  end if;

  -- Check allowed status transition: shipped -> released
  if v_status != 'shipped' then
    raise exception 'Order is not in shipped status, current status: %', v_status;
  end if;

  -- Update status
  update public.orders
  set status = 'released'
  where id = p_order_id;

  return 'released';
end;
$$;

-- Function: refund_order - seller moves order from paid or shipped to refunded (R4, R5)
create or replace function public.refund_order(p_order_id bigint)
returns text language plpgsql security definer as $$
declare
  v_status text;
  v_seller_id uuid;
  v_buyer_id uuid;
begin
  -- Check order exists
  select status, seller_id, buyer_id into v_status, v_seller_id, v_buyer_id
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order with ID % not found', p_order_id using errortext = 'Order not found';
  end if;

  -- Check caller is the seller
  if auth.role() != 'service_role' and v_seller_id != auth.uid() then
    raise exception 'Only the seller can refund order';
  end if;

  -- Check allowed status transition: paid or shipped -> refunded
  if v_status not in ('paid', 'shipped') then
    raise exception 'Order is not in paid or shipped status, current status: %', v_status;
  end if;

  -- Update status
  update public.orders
  set status = 'refunded'
  where id = p_order_id;

  return 'refunded';
end;
$$;

