  if not found then
    raise exception 'Order with id % not found', p_order_id using errortype = 'invalid_parameter_value';
  end if;

  -- R5: caller must be the seller
  if v_seller is distinct from auth.uid() then
    raise exception 'Only the order seller can mark shipped', using errortype = 'invalid_auth';
  end if;

  -- R5: status must be paid
  if v_status != 'paid' then
    raise exception 'Order is not in pending_payment status', using errortype = 'invalid_state';
  end if;

  -- Update status
  update public.orders set status = 'shipped' where id = p_order_id;

  return 'shipped';
end;
$$ security definer;

-- Create release_funds function (R4: buyer moves shipped -> released, R5: validation)
create function public.release_funds(p_order_id bigint) returns text language plpgsql strict as $$
declare
  v_status text;
  v_seller uuid;
  v_buyer uuid;
begin
  select status, seller_id, buyer_id into v_status, v_seller, v_buyer
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order with id % not found', p_order_id using errortype = 'invalid_parameter_value';
  end if;

  -- R5: caller must be the buyer
  if v_buyer is distinct from auth.uid() then
    raise exception 'Only the order buyer can release funds', using errortype = 'invalid_auth';
  end if;

  -- R5: status must be shipped
  if v_status != 'shipped' then
    raise exception 'Order is not in shipped status', using errortype = 'invalid_state';
  end if;

  update public.orders set status = 'released' where id = p_order_id;

  return 'released';
end;
$$ security definer;

-- Create refund_order function (R4: seller moves paid/shipped -> refunded, R5: validation)
create function public.refund_order(p_order_id bigint) returns text language plpgsql strict as $$
declare
  v_status text;
  v_seller uuid;
  v_buyer uuid;
begin
  select status, seller_id, buyer_id into v_status, v_seller, v_buyer
  from public.orders
  where id = p_order_id;

  if not found then
    raise exception 'Order with id % not found', p_order_id using errortype = 'invalid_parameter_value';
  end if;

  -- R5: caller must be the seller
  if v_seller is distinct from auth.uid() then
    raise exception 'Only the order seller can refund', using errortype = 'invalid_auth';
  end if;

  -- R5: status must be paid or shipped
  if v_status not in ('paid', 'shipped') then
    raise exception 'Order is not in a refundable status', using errortype = 'invalid_state';
  end if;

  update public.orders set status = 'refunded' where id = p_order_id;

  return 'refunded';
end;
$$ security definer;

-- Grants for authenticated users (R1-R7)
grant usage on schema public to authenticated;
grant select on public.listings to authenticated;
grant select on public.orders to authenticated;

