-- Function: sign_envelope - records caller's signature and updates status
create or replace function public.sign_envelope(p_envelope_id bigint) returns text language plpgsql strict as $$
declare
  v_sender_id uuid;
  v_status text;
  v_order integer;
  v_prev_signed boolean;
  v_recipient_count integer;
  v_signed_count integer;
begin
  -- 1. Validate envelope exists and is in 'sent' status
  select status, sender_id into v_status, v_sender_id from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope not found';
  end if;
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- 2. Validate caller is a recipient of this envelope
  if not exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
    and user_id = auth.uid()
  ) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- 3. Validate caller has not already signed
  if exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id
    and user_id = auth.uid()
    and signed_at is not null
  ) then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- 4. Check that all earlier signers in sign_order have signed
  -- Get the sign_order of the caller
  select sign_order into v_order from public.envelope_recipients
  where envelope_id = p_envelope_id
  and user_id = auth.uid();

  -- Check all recipients with lower sign_order have signed
  if v_order > 1 then
    select count(*) into v_signed_count from public.envelope_recipients
    where envelope_id = p_envelope_id
    and sign_order < v_order
    and signed_at is not null;

    if v_signed_count < v_order - 1 then
      raise exception 'An earlier recipient in sign_order has not signed yet';
    end if;
  end if;

  -- 5. Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
  and user_id = auth.uid();

  -- 6. Check if all recipients have signed and update status
  if check_all_signed(p_envelope_id) then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
  end if;

  -- Return current status
  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

-- Function: void_envelope - lets the sender cancel an envelope that is still 'sent'
create or replace function public.void_envelope(p_envelope_id bigint) returns text language plpgsql strict as $$
declare
  v_sender_id uuid;
  v_status text;
begin
  -- 1. Validate envelope exists
  select status, sender_id into v_status, v_sender_id from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope not found';
  end if;

  -- 2. Only the sender can void the envelope
  if auth.uid() != v_sender_id then
    raise exception 'Only the sender can void this envelope';
  end if;

  -- 3. Envelope must be in 'sent' status
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- 4. Void the envelope
  update public.envelopes set status = 'voided' where id = p_envelope_id;

  -- 5. Return current status
  select status into v_status from public.envelopes where id = p_envelope_id;
  return v_status;
end;
$$;

