-- Enable RLS on both tables
alter table public.envelopes enable row level security;
alter table public.envelope_recipients enable row level security;

-- Helper: check if all recipients have signed
create or replace function public.all_recipients_signed(p_envelope_id bigint) returns boolean language sql immutable as $$
  select count(*) = 0
  from public.envelope_recipients
  where envelope_id = p_envelope_id
    and signed_at is null;
$$;

-- Policy: Senders and recipients can see their envelopes and the full recipient list
create policy "Senders and recipients can view envelopes and recipients"
  on public.envelopes
  for select
  using (
    sender_id = auth.uid()
    or exists (
      select 1 from public.envelope_recipients er
      where er.envelope_id = id
        and er.user_id = auth.uid()
    )
  );

create policy "Senders and recipients can view recipients"
  on public.envelope_recipients
  for select
  using (
    user_id = auth.uid()
    or exists (
      select 1 from public.envelopes e
      where e.id = envelope_id
        and (e.sender_id = auth.uid()
             or exists (
               select 1 from public.envelope_recipients er2
               where er2.envelope_id = e.id
                 and er2.user_id = auth.uid()
            ))
    )
  );

-- Policy: Prevent direct insert/update/delete from the app
create policy "Prevent app-level changes to envelopes"
  on public.envelopes
  for all
  using (false);

create policy "Prevent app-level changes to recipients"
  on public.envelope_recipients
  for all
  using (false);

-- sign_envelope RPC wrapper (SECURITY INVOKER so it runs with the caller's RLS)
create or replace function public.sign_envelope(p_envelope_id bigint) returns text language plpgsql security invoker as $$
declare
  v_status text;
  v_sender_id uuid;
  v_already_signed boolean;
  v_earlier_signed boolean;
begin
  -- 1. Resolve caller's identity and check they are a recipient
  select sender_id into v_sender_id from public.envelopes where id = p_envelope_id;
  if not exists (select 1 from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid()) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- 2. Check envelope status is 'sent'
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status != 'sent' then
    raise exception 'Envelope is not in ''sent'' status';
  end if;

  -- 3. Check caller hasn't already signed
  select into v_already_signed exists (
    select 1 from public.envelope_recipients
    where envelope_id = p_envelope_id and user_id = auth.uid()
      and signed_at is not null
  );
  if v_already_signed then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- 4. Check all earlier sign_orders have signed
  select into v_earlier_signed exists (
    select 1 from public.envelope_recipients er
    where er.envelope_id = p_envelope_id
      and er.sign_order < (select sign_order from public.envelope_recipients where envelope_id = p_envelope_id and user_id = auth.uid())
      and er.signed_at is null
  );
  if v_earlier_signed then
    raise exception 'An earlier recipient in sign_order has not signed yet';
  end if;

  -- 5. Record the signature
  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = auth.uid();

  -- 6. Return new status
  if public.all_recipients_signed(p_envelope_id) then
    update public.envelopes set status = 'completed' where id = p_envelope_id;
    return 'completed';
  else
    return 'sent';
  end if;
end;
$$;

-- void_envelope RPC wrapper (SECURITY INVOKER)
create or replace function public.void_envelope(p_envelope_id bigint) returns text language plpgsql security invoker as $$
declare
  v_status text;
begin
  -- 1. Check caller is the sender
  select status into v_status from public.envelopes where id = p_envelope_id;
  if v_status is null then
    raise exception 'Envelope not found';
  end if;
  if v_status != 'sent' then
    raise exception 'Envelope is not in ''sent'' status and cannot be voided';
  end if;

  -- 2. Verify caller is the sender
  if (select sender_id from public.envelopes where id = p_envelope_id) != auth.uid() then
    raise exception 'Only the sender can void this envelope';
  end if;

  -- 3. Void the envelope
  update public.envelopes set status = 'voided' where id = p_envelope_id and status = 'sent';

  return 'voided';
end;
$$;

-- Grant authenticated users the ability to execute the RPCs
grant execute on public.sign_envelope to authenticated;
grant execute on public.void_envelope to authenticated;

-- Ensure service_role bypasses RLS (already has full access by default)
-- No additional grants needed for service_role; it bypasses RLS automatically.
