  on public.envelopes
  for select
  using (
    sender_id = auth.uid()
    or exists (
      select 1
      from public.envelope_recipients r
      where r.envelope_id = id
        and r.user_id = auth.uid()
    )
  );

create policy "Senders and recipients can view recipient list"
  on public.envelope_recipients
  for select
  using (
    exists (
      select 1
      from public.envelopes e
      where e.id = envelope_id
        and (e.sender_id = auth.uid()
             or exists (
               select 1
               from public.envelope_recipients r
               where r.envelope_id = e.id
                 and r.user_id = auth.uid()
             ))
    )
  );

-- Policy: Server-side service role keeps full access
create policy "Service role full access on envelopes"
  on public.envelopes
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

create policy "Service role full access on recipients"
  on public.envelope_recipients
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

-- Policy: Nobody can modify envelopes or recipients directly
create policy "No direct DML on envelopes"
  on public.envelopes
  for all
  using (false)
  with check (false);

create policy "No direct DML on recipients"
  on public.envelope_recipients
  for all
  using (false)
  with check (false);

-- Function: sign_envelope
create or replace function public.sign_envelope(p_envelope_id bigint) returns text language sql strict as $$
declare
  v_status text;
  v_sender_id uuid;
  v_recipient_count integer;
  v_signed_count integer;
  v_order_to_check integer;
  v_already_signed boolean;
  v_earlier_signed boolean;
begin
  -- Look up envelope status and sender
  select e.status, e.sender_id
    into v_status, v_sender_id
    from public.envelopes e
    where e.id = p_envelope_id;

  -- If envelope is not sent, raise error
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Check if the caller is a recipient of this envelope
  if not exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = auth.uid()
  ) then
    raise exception 'Caller is not a recipient of this envelope';
  end if;

  -- Check if caller has already signed
  if exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = auth.uid()
      and r.signed_at is not null
  ) then
    raise exception 'Caller has already signed this envelope';
  end if;

  -- Count recipients and how many have signed
  select count(*), count(r.signed_at)
    into v_recipient_count, v_signed_count
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id;

  -- Determine the sign_order of the caller
  select r.sign_order
    into v_order_to_check
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = auth.uid();

  -- Check that all earlier recipients have signed
  if v_order_to_check > 1 then
    if not exists (
      select 1
      from public.envelope_recipients r
      where r.envelope_id = p_envelope_id
        and r.sign_order < v_order_to_check
        and r.signed_at is not null
    ) then
      raise exception 'An earlier recipient in sign_order has not signed yet';
    end if;
  end if;

  -- Record the signature
  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = auth.uid();

  -- Check if all have signed and update status
  if check_all_signed(p_envelope_id) then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
  end if;

  -- Return current status
  return (select status from public.envelopes where id = p_envelope_id);
end;
$$ security invoker;

-- Function: void_envelope
create or replace function public.void_envelope(p_envelope_id bigint) returns text language sql strict as $$
declare
  v_status text;
begin
  -- Look up envelope status
  select status
    into v_status
    from public.envelopes
    where id = p_envelope_id;

  -- Only sender can void, and only if status is sent
  if v_status != 'sent' then
    raise exception 'Envelope is not in sent status';
  end if;

  -- Void the envelope
  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id;

  return 'voided';
exception
  when others then
    -- Re-raise the error without changing anything
    raise exception 'void_envelope failed: %', sqlstate;
end;
$$ security invoker;
