-- Writers can read their own articles and all published articles; Editors can read everything; Anonymous can read published
create policy "Read published and own articles" on public.articles
  for select
  using (
    -- Anonymous and authenticated can read published articles
    (status = 'published') or
    -- Writers can read their own articles
    (author_id = auth.uid()) or
    -- Editors can read all articles
    (auth.role() = 'authenticated' and exists (select 1 from public.editors where user_id = auth.uid()))
  );

-- Writers can create drafts as themselves
create policy "Writers insert drafts" on public.articles
  for insert
  with check (author_id = auth.uid() and status = 'draft');

-- Writers can edit their own drafts (status = 'draft' ensures they only edit drafts)
create policy "Writers edit own drafts" on public.articles
  for update
  using (author_id = auth.uid() and status = 'draft')
  with check (author_id = auth.uid() and status = 'draft');

-- Editors can edit articles in review, publish them, or send back to draft
create policy "Editors update articles" on public.articles
  for update
  using (
    auth.role() = 'authenticated' and exists (select 1 from public.editors where user_id = auth.uid())
  )
  with check (
    -- Editors can set status to in_review, published, or draft
    (status in ('in_review', 'published', 'draft')) and
    -- Once published, no changes allowed (enforced by check option + published_at guard below)
    (not (status = 'published' and published_at is not null))
  );

-- Editors cannot change drafts or published articles via the app UI path (RLS blocks; also application logic)
-- Explicitly block editors from updating drafts or published articles
create policy "Editors block drafts/published" on public.articles
  for update
  using (
    auth.role() = 'authenticated' and exists (select 1 from public.editors where user_id = auth.uid())
    and (
      (status = 'draft') or
      (status = 'published' and published_at is not null)
    )
  )
  with check (
    auth.role() = 'authenticated' and exists (select 1 from public.editors where user_id = auth.uid())
    and (
      (status = 'draft') or
      (status = 'published' and published_at is not null)
    )
  );

-- Writers can delete only their own drafts
create policy "Writers delete own drafts" on public.articles
  for delete
  using (author_id = auth.uid() and status = 'draft');

-- Once published, an article can no longer be changed through the app.
-- We enforce this at the RLS level: if published_at is set, no updates allowed for anyone except service_role.
-- The existing "Editors update articles" policy combined with this ensures immutability.
-- Additional guard: prevent updates to published articles even by editors via RLS.
-- (The above policies already restrict based on status; we add a explicit check for clarity.)
create policy "Published articles immutable" on public.articles
  for update
  using (status = 'published' and published_at is not null)
  with check (false);

-- Writers can see whether they themselves are an editor
-- No direct policy needed; we provide a view for convenience (optional)
create or replace view public.is_editor as
select true as is_editor
where exists (select 1 from public.editors where user_id = auth.uid());

-- Grant usage on auth schema for RLS functions
grant usage on schema auth to public;

-- Revoke public access to editors table (nobody can change editors through the app)
revoke all on public.editors from public;
grant select on public.editors to authenticated;
-- Allow authenticated users to check if they are an editor (via the view)
grant select on public.is_editor to authenticated;

-- Service role retains full access (implicit via bypassrls, no additional grant needed)
