-- Enable Row Level Security on all relevant tables
alter table public.referral_codes enable row level security;
alter table public.referrals enable row level security;
alter table public.credits enable row level security;

-- Helper function to count referrals made by a user
create or replace function public.count_referrals(p_user_id uuid)
returns bigint language sql immutable strict as $$
  select count(*) from public.referrals where referrer_id = p_user_id;
$$;

-- Policy: Users can see their own referral code
create policy "Users can see own referral code" on public.referral_codes
for select using (user_id = auth.uid());

-- Policy: Users can see referrals they made or received
create policy "Users can see own referrals" on public.referrals
for select using (referrer_id = auth.uid() or referee_id = auth.uid());

-- Policy: Users can see their own credits
create policy "Users can see own credits" on public.credits
for select using (user_id = auth.uid());

-- Policy: Nobody can modify referral codes
create policy "No modifications to referral codes" on public.referral_codes
for all using (false) with check (false);

-- Policy: Nobody can modify referrals
create policy "No modifications to referrals" on public.referrals
for all using (false) with check (false);

-- Policy: Nobody can modify credits
create policy "No modifications to credits" on public.credits
for all using (false) with check (false);

-- Create the redeem_referral function
create or replace function public.redeem_referral(p_code text)
returns bigint language plpgsql security definer as $$
declare
  v_code_user uuid;
  v_caller_id uuid;
  v_referrer_id uuid;
  v_referral_count bigint;
  v_existing_referral bigint;
begin
  -- 1. Check caller is signed in
  v_caller_id := auth.uid();
  if v_caller_id is null then
    raise exception 'User not signed in';
  end if;

  -- 2. Check code exists
  select user_id into v_code_user from public.referral_codes where code = p_code;
  if v_code_user is null then
    raise exception 'Referral code does not exist';
  end if;

  -- 3. Check caller is not the code owner
  if v_code_user = v_caller_id then
    raise exception 'Caller cannot use own referral code';
  end if;

  -- 4. Check caller has not already redeemed a referral
  select count(*) into v_existing_referral from public.referrals where referee_id = v_caller_id;
  if v_existing_referral > 0 then
    raise exception 'Caller has already redeemed a referral code';
  end if;

  -- 5. Check code owner has fewer than 5 referrals
  select public.count_referrals(v_code_user) into v_referral_count;
  if v_referral_count >= 5 then
    raise exception 'Code owner already has 5 referrals';
  end if;

  -- 6. Record the referral
  insert into public.referrals (referrer_id, referee_id, created_at)
    values (v_code_user, v_caller_id, now())
    returning id into v_referral_id;

  -- 7. Give 100 credits to the new user
  insert into public.credits (user_id, amount, reason)
    values (v_caller_id, 100, 'referral_redeem');

  -- 8. Give 100 credits to the code owner
  insert into public.credits (user_id, amount, reason)
    values (v_code_user, 100, 'referral_redeem');

  return v_referral_id;
end;
$$;

-- Grant usage of the function to authenticated users
grant execute on public.redeem_referral to authenticated;

-- Grant select on tables to authenticated users (for R1)
grant select on public.referral_codes to authenticated;
grant select on public.referrals to authenticated;
grant select on public.credits to authenticated;

-- Revoke all from anon (R5: anonymous visitors cannot see or change anything)
revoke all on public.referral_codes from anon;
revoke all on public.referrals from anon;
revoke all on public.credits from anon;
