-- R1: Members can see their household's items
create policy "shopping_items_select" on public.shopping_items
  for select using (
    household_id in (
      select household_id from public.household_members where user_id = get_current_user_id()
    )
  );

-- R2: Members can add items as themselves
create policy "shopping_items_insert" on public.shopping_items
  for insert with check (
    household_id in (
      select household_id from public.household_members where user_id = get_current_user_id()
    )
    and added_by = get_current_user_id()
  );

-- R3: Members can claim an unclaimed item for themselves and unclaim items they claimed
-- Insert/update claimed_by to current user only if item is unclaimed or already claimed by them
create policy "shopping_items_claim" on public.shopping_items
  for update using (
    -- Allow update only when setting claimed_by to current user (claim) or null (unclaim)
    (claimed_by = get_current_user_id() or claimed_by is null)
    and household_id in (
      select household_id from public.household_members where user_id = get_current_user_id()
    )
  )
  with check (
    -- On claim: set claimed_by to current user; on unclaim: set to null
    ( claimed_by = get_current_user_id() 
      or claimed_by is null )
  );

-- R4: Only the member who claimed an item can mark it bought; bought item stays claimed
create policy "shopping_items_bought" on public.shopping_items
  for update using (
    -- Only allow update if the item is claimed by the current user and is being marked bought
    claimed_by = get_current_user_id()
    and household_id in (
      select household_id from public.household_members where user_id = get_current_user_id()
    )
  )
  with check (
    -- Bought item stays claimed; no other fields may change
    claimed_by = get_current_user_id()
    and is_bought = true
  );

-- R5: The member who added an item can delete it while it is not bought
create policy "shopping_items_delete" on public.shopping_items
  for delete using (
    -- Deleter must be the adder and item must not be bought
    added_by = get_current_user_id()
    and is_bought = false
    and household_id in (
      select household_id from public.household_members where user_id = get_current_user_id()
    )
  );

