for all using (false);

create policy "No modifications to credits" on public.credits
for all using (false);

-- Create the redeem_referral function
create or replace function public.redeem_referral(p_code text)
returns bigint language plpgsql security definer as $$
declare
  v_code_user uuid;
  v_caller_id uuid := auth.uid();
  v_referrer_id uuid;
  v_referral_count bigint;
  v_new_referral_id bigint;
begin
  -- Check: caller must be signed in
  if v_caller_id is null then
    raise exception 'Caller must be signed in';
  end if;

  -- Check: code must exist
  select user_id into v_code_user from public.referral_codes where code = p_code;
  if v_code_user is null then
    raise exception 'Referral code does not exist';
  end if;

  -- Check: caller cannot redeem own code
  if v_code_user = v_caller_id then
    raise exception 'Cannot redeem own referral code';
  end if;

  -- Check: caller has not already redeemed a referral
  if exists (select 1 from public.referrals where referee_id = v_caller_id) then
    raise exception 'Caller has already redeemed a referral code';
  end if;

  -- Check: code owner must have less than 5 referrals
  select count_referrals_by_owner(v_code_user) into v_referral_count;
  if v_referral_count >= 5 then
    raise exception 'Code owner already has 5 referrals';
  end if;

  -- Insert the referral record
  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_code_user, v_caller_id, now())
  returning id into v_new_referral_id;

  -- Give 100 credits to the new user
  insert into public.credits (user_id, amount, reason)
  values (v_caller_id, 100, 'referral_redeem');

  -- Give 100 credits to the code owner
  insert into public.credits (user_id, amount, reason)
  values (v_code_user, 100, 'referral_redeem');

  return v_new_referral_id;
end;
$$;

-- Grant usage of the function to authenticated users
