  for select using (
    (deleted_at is null) or
    (auth.role() = 'service_role') or
    (public.is_org_admin(org_id))
  );

-- R2: Members can create records in their org; admins can delete (set deleted_at)
create policy "records_r2_insert" on public.records
  for insert with check (
    exists (
      select 1 from public.org_members
      where org_id = records.org_id
        and user_id = auth.uid()
        and role = 'member'
    )
  );

create policy "records_r2_update" on public.records
  for update using (
    (deleted_at is null) or public.is_org_admin(org_id)
  )
  with check (
    (deleted_at is null) or public.is_org_admin(org_id)
  );

create policy "records_r2_delete" on public.records
  for update using (
    deleted_at is not null
  )
  with check (
    public.is_org_admin(org_id)
  );

-- R3: Trigger to auto-populate audit_log on insert/update
create or replace function public.audit_trigger()
returns trigger language plpgsql as $$
begin
  if (TG_OP = 'INSERT') then
    insert into public.audit_log (record_id, action, actor)
      values (new.id, 'insert', auth.uid());
    return new;
  elsif (TG_OP = 'UPDATE') then
    insert into public.audit_log (record_id, action, actor)
      values (new.id, 'update', auth.uid());
    return new;
  end if;
end;
$$;

create trigger records_audit_trigger
  after insert or update on public.records
  for each row execute function public.audit_trigger();

-- R4: Admins can read audit rows of their org; members cannot
create policy "audit_log_r4_admin" on public.audit_log
  for select using (
    exists (
      select 1 from public.org_members om
      where om.org_id = (
        select org_id from public.records where id = audit_log.record_id
      )
        and om.user_id = auth.uid()
        and om.role = 'admin'
    )
  );

-- R5: restore_record function
create or replace function public.restore_record(p_record_id bigint)
returns void language plpgsql as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
  v_org_member_count bigint;
begin
  -- Get record details and organization
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check admin of the record's organization
  if not public.is_org_admin(v_org_id) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check deleted within last 30 days
  if v_deleted_at < now() - interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago';
  end if;

  -- Perform restore
  update public.records set deleted_at = null where id = p_record_id;
end;
$$;

