create trigger "records_insert_audit"
  after insert on public.records
  for each row execute procedure public.add_audit_insert();

-- Trigger for updates
create trigger "records_update_audit"
  after update on public.records
  for each row execute procedure public.add_audit_update();

-- R4: Admins can read audit rows of their org's records; members cannot
