-- R5: restore_record function
create or replace function public.restore_record(p_record_id bigint) returns void
language plpgsql
security definer
as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
  v_deleted_interval interval;
begin
  -- Get record details
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if v_org_id is null then
    raise exception 'Record not found';
  end if;

  -- Check caller is admin of the organization
  if not exists (
    select 1 from public.org_members
    where org_id = v_org_id
    and user_id = auth.uid()
    and role = 'admin'
  ) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check deletion was within last 30 days
  v_deleted_interval := now() - v_deleted_at;
  if v_deleted_interval > interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago and cannot be restored';
  end if;

  -- Clear deleted_at
  update public.records set deleted_at = null where id = p_record_id;
end;
$$;

