-- Enable Row Level Security on all applicable tables
alter table public.org_members enable row level security;
alter table public.records enable row level security;
alter table public.audit_log enable row level security;

-- Helper function to get the organization ID of the current user
create function public.get_user_org_id() returns bigint language sql stable as $$
  select coalesce(org_id, 0) from public.org_members where user_id = auth.uid();
$$;

-- R1: Members can see their own memberships and their organization's non-deleted records.
-- Admins can also see deleted records.
create policy "org_members_select_policy" on public.org_members
  for select using (user_id = auth.uid());

create policy "records_select_policy" on public.records
  for select using (
    -- Users can see records from their own organizations
    org_id = public.get_user_org_id() 
    -- AND either not deleted, or user is admin of that org
    and (deleted_at is null or exists (
      select 1 from public.org_members om2
      where om2.org_id = records.org_id
      and om2.user_id = auth.uid()
      and om2.role = 'admin'
    ))
  );

-- R2: Members can create records in their organization and edit non-deleted records.
-- Only admins can delete (set deleted_at) a record.
create policy "records_insert_policy" on public.records
  for insert with check (org_id = public.get_user_org_id());

create policy "records_update_policy" on public.records
  for update using (org_id = public.get_user_org_id())
  with check (
    org_id = public.get_user_org_id()
    and (deleted_at is null or exists (
      select 1 from public.org_members om2
      where om2.org_id = records.org_id
      and om2.user_id = auth.uid()
      and om2.role = 'admin'
    ))
  );

-- R3: Every insert and update of a record adds an audit_log row.
-- Trigger handles both insert and update actions.
create or replace function public.log_record_action() returns trigger language plpgsql stable as $$
begin
  if (TG_OP = 'INSERT') then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'insert', auth.uid());
  elsif (TG_OP = 'UPDATE') then
    insert into public.audit_log (record_id, action, actor)
    values (new.id, 'update', auth.uid());
  end if;
  return new;
end;
$$;

create trigger record_audit_trigger
  after insert or update on public.records
  for each row execute function public.log_record_action();

-- R4: Admins can read the audit rows of their organization's records; members cannot.
create policy "audit_log_select_policy" on public.audit_log
  for select using (
    -- Find the organization of the record in the audit log
    exists (
      select 1 from public.records r
      where r.id = audit_log.record_id
      and r.org_id = (
        select org_id from public.org_members om
        where om.user_id = auth.uid()
      )
    )
    -- Admins of that organization can read; members cannot
    and exists (
      select 1 from public.org_members om2
      where om2.org_id = (
        select org_id from public.records r2 where r2.id = audit_log.record_id
      )
      and om2.user_id = auth.uid()
      and om2.role = 'admin'
    )
  );

-- R5: restore_record function - clears deleted_at with safety checks
create or replace function public.restore_record(p_record_id bigint) returns void language plpgsql stable as $$
declare
  v_org_id bigint;
  v_deleted_at timestamptz;
  v_org_member_count integer;
begin
  -- Check caller is admin of the record's organization
  select org_id, deleted_at into v_org_id, v_deleted_at
  from public.records
  where id = p_record_id;

  if not exists (
    select 1 from public.org_members om
    where om.org_id = v_org_id
    and om.user_id = auth.uid()
    and om.role = 'admin'
  ) then
    raise exception 'Only admins can restore records';
  end if;

  -- Check record is deleted
  if v_deleted_at is null then
    raise exception 'Record is not deleted';
  end if;

  -- Check deletion was within last 30 days
  if v_deleted_at < now() - interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago and cannot be restored';
  end if;

  -- Clear deleted_at
  update public.records set deleted_at = null where id = p_record_id;
end;
$$;

-- R6: Grant full access to authenticated users and service_role where appropriate
-- Grant select on org_members to authenticated users (policy handles specifics)
grant usage on schema public to authenticated;
grant all on public.org_members to service_role;
grant all on public.records to service_role;
grant all on public.audit_log to service_role;

-- Grant execute on functions to authenticated users
grant execute on function public.get_user_org_id() to authenticated;
grant execute on function public.restore_record(p_record_id bigint) to authenticated;
