-- R1 & R2: Records policies
-- Members can see their org's non-deleted records; admins see all including deleted
create policy "org_members_select_own_records" on public.records
for select using (
  -- Allow if user is a member of the org
  exists (select 1 from public.org_members where org_id = records.org_id and user_id = auth.uid())
  and (deleted_at is null or public.is_org_admin(records.org_id))
);

-- Members can create records in their org; admins have full control via service_role
create policy "org_members_insert_records" on public.records
for insert with check (
  exists (select 1 from public.org_members where org_id = org_id and user_id = auth.uid())
);

-- Members can update non-deleted records in their org; only admins can set deleted_at
create policy "org_members_update_records" on public.records
for update using (
  exists (select 1 from public.org_members where org_id = records.org_id and user_id = auth.uid())
)
with check (
  -- Prevent non-admins from setting deleted_at
  (deleted_at is null or public.is_org_admin(records.org_id))
);

-- R3: Audit log triggers for insert and update
create or replace function public.audit_insert_trigger() returns trigger
language plpgsql
security definer
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (new.id, 'insert', auth.uid());
  return new;
end;
$$;

create or replace function public.audit_update_trigger() returns trigger
language plpgsql
security definer
as $$
begin
  insert into public.audit_log (record_id, action, actor)
  values (new.id, 'update', auth.uid());
  return new;
end;
$$;

create trigger records_insert_audit
  after insert on public.records
  for each row execute function public.audit_insert_trigger;

create trigger records_update_audit
  after update on public.records
  for each row execute function public.audit_update_trigger;

-- R4: Audit log policies
-- Admins can read audit rows of their organization's records; members cannot
create policy "org_admins_select_audit" on public.audit_log
for select using (
  exists (
    select 1 from public.records r
    join public.org_members om on om.org_id = r.org_id
    where r.id = audit_log.record_id
    and om.user_id = auth.uid()
    and om.role = 'admin'
  )
);

-- R5: restore_record function
create or replace function public.restore_record(p_record_id bigint) returns void
language plpgsql
security definer
as $$
declare
  v_record public.records%rowtype;
  v_org_id bigint;
  v_org_member public.org_members%rowtype;
  v_deleted_at timestamptz;
  v_org_admin boolean;
begin
  -- Fetch the record
  select * into v_record from public.records where id = p_record_id;
  if not found then
    raise exception 'Record with id % not found', p_record_id using errcontext;
  end if;

  v_deleted_at := v_record.deleted_at;
  if v_deleted_at is null then
    raise exception 'Record % is not deleted', p_record_id using errcontext;
  end if;

  -- Determine organization and check admin status
  v_org_id := v_record.org_id;
  select * into v_org_member from public.org_members where org_id = v_org_id and user_id = auth.uid();
  if not found then
    raise exception 'You are not a member of the organization for record %', p_record_id using errcontext;
  end if;
  v_org_admin := v_org_member.role = 'admin' or auth.role() = 'service_role';

  if not v_org_admin then
    raise exception 'Only admins can restore records';
  end if;

  -- Check deletion time (within last 30 days)
  if v_deleted_at < now() - interval '30 days' then
    raise exception 'Record was deleted more than 30 days ago and cannot be restored';
  end if;

  -- Clear deleted_at
  update public.records set deleted_at = null where id = p_record_id;
end;
$$;

-- Grant service_role full access (already implied but explicit for clarity)
grant all on public.org_members to service_role;
grant all on public.records to service_role;
grant all on public.audit_log to service_role;
grant execute on public.is_org_admin to authenticated;
grant execute on public.restore_record to authenticated;
