      select 1 from public.residents
      where unit_id = permits.unit_id
      and user_id = auth.uid()
    )
    -- Can only update the plate column; validity and revoke are protected by check option below
    and current_setting('permissions.update', true) = 'plate'
  )
  with check (
    -- Only the plate column may be updated; validity and revoke remain unchanged
    case when new.plate is distinct from old.plate then
      (new.plate is not null)
      and (new.valid_until is null or new.valid_until <= (current_setting('permissions.valid_until_max')::timestamp)::date + interval '365 days')
      and (new.revoked is not distinct from old.revoked)
