  for update using (
    auth.role() = 'authenticated'
    and exists (select 1 from public.residents where unit_id = unit_id and user_id = auth.uid())
  )
  with check (
    -- Only plate may change; validity and revoked must stay as-is
    plate = values->>'plate'
    and not (valid_until is distinct from (current_setting('plates.new_valid_until', true, false)::date)) -- placeholder; actual enforcement via trigger
    and not (revoked is distinct from false) -- prevent un-revoke
  );

-- R4: HOA admins revoke permits; nobody can un-revoke
create policy "hoa_admins_revoke_permit" on public.permits
  for update using (
    auth.role() = 'service_role' or (auth.role() = 'authenticated' and exists (select 1 from public.hoa_admins where user_id = auth.uid()))
  )
  with check (
    revoked = true
  );

