select p.* from public.permits p
join public.residents r on p.unit_id = r.unit_id
where r.user_id = auth.uid();

-- Grant access to the view
grant select on public.resident_permits to authenticated;

-- Triggers to enforce business rules (R2/R3/R4)
-- Trigger: prevent inserting permit if unit already has 2 active permits
create trigger trg_check_active_permit_count
  before insert on public.permits
  for each row execute procedure public.check_active_permit_count();

-- Trigger: prevent updating validity/revoke status on permits (R3)
create trigger trg_protect_permit_fields
  before update on public.permits
  for each row execute procedure public.protect_permit_fields();

-- Helper functions for triggers
create function public.check_active_permit_count() returns trigger language sql strict as $$
begin
  if (select count_active_permits(new.unit_id)) >= 2 then
    signal sqlstate '45000' set message_text = 'Unit already has 2 active permits';
  end if;
  return new;
end$$;

create function public.protect_permit_fields() returns trigger language sql strict as $$
begin
  -- Residents cannot change validity or revoke status
  if new.valid_until != old.valid_until then
    signal sqlstate '45000' set message_text = 'Cannot change validity';
  end if;
  if new.revoked != old.revoked then
    signal sqlstate '45000' set message_text = 'Cannot change revoke status';
  end if;
  return new;
end$$;
