      from public.residents
      where residents.unit_id = permits.unit_id
      and residents.user_id = auth.uid()
    )
    or auth.role() = 'hoa_admin'
  );

create policy "HOA admins see all permits"
  on public.permits for select
  using (auth.role() = 'hoa_admin');

-- R2: Insert policy - residents add permits for their unit (max 2 active per unit)
