  on public.permits for insert
  with check (
    exists (
      select 1
      from public.residents
      where residents.unit_id = unit_id
      and residents.user_id = auth.uid()
    )
    and (
      select count(*)
      from public.permits
      where unit_id = unit_id
      and not revoked
      and valid_until >= current_date
    ) < 2
  );

-- R3: Update policy - residents change plate only, cannot touch validity or revoked
create policy "Residents update plate only"
  on public.permits for update
  using (
    exists (
      select 1
      from public.residents
      where residents.unit_id = permits.unit_id
      and residents.user_id = auth.uid()
    )
    and plate is distinct from null -- allows the column to be set
    and not revoked -- prevent un-revoking
    and valid_until = valid_until -- enforce no change to validity (kept in check option)
  )
  with check (
    plate is not null
    and revoked = false -- cannot set revoked=true
    and valid_until >= current_date -- cannot set past date
  );

-- R4: HOA admins revoke permits; nobody can un-revoke
create policy "HOA admins revoke permits"
  on public.permits for update
  using (auth.role() = 'hoa_admin')
  with check (revoked = true);

-- R5: Nobody changes residents or hoa_admins (no policies on those tables needed beyond RLS)
-- R6: Service role bypasses RLS inherently; no additional policy needed.

