-- The break_glass function implements the break-glass logic
create or replace function public.break_glass(p_patient_id bigint, p_reason text)
  returns timestamptz
  language plpgsql
  security definer
  set search_path = public
as $$
declare
  v_clinician_id uuid;
  v_reason trimmed;
begin
  -- Check caller is a clinician
  select user_id into v_clinician_id
  from public.clinicians
  where user_id = auth.uid();

  if v_clinician_id is null then
    raise exception 'Only clinicians can break the glass';
  end if;

  -- Check patient exists
  if not exists (select 1 from public.patients where id = p_patient_id) then
    raise exception 'Patient does not exist';
  end if;

  -- Check reason length (ignoring surrounding spaces)
  v_reason := trim(p_reason);
  if char_length(v_reason) < 10 then
    raise exception 'Reason must be at least 10 characters';
  end if;

  -- Insert the break-glass grant (expires in one hour)
  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_clinician_id, v_reason, now() + interval '1 hour');

  return now() + interval '1 hour';
end;
$$;

