-- transfer_stock function: enforces R4 rules
create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
) returns integer language sql security invoker as $$
begin
  -- R4: caller must be staff of source warehouse
  if not is_staff_of(p_from, auth.uid()) then
    raise exception 'Caller is not staff of the source warehouse using error';
  end if;

  -- R4: quantity must be positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive using error';
  end if;

  -- R4: source and destination must be different and exist
  if p_from = p_to then
    raise exception 'Source and destination must be different using error';
  end if;

  if not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'Destination warehouse does not exist using error';
  end if;

  -- R4: source must have enough stock
  if not exists (
    select 1 from public.stock
    where warehouse_id = p_from
    and sku = p_sku
    and qty >= p_qty
  ) then
    raise exception 'Source does not have enough stock using error';
  end if;

  -- Deduct from source
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from
    and sku = p_sku;

  -- If source stock becomes zero, remove the row
  if not exists (
    select 1 from public.stock
    where warehouse_id = p_from
    and sku = p_sku
  ) then
    delete from public.stock
    where warehouse_id = p_from
      and sku = p_sku;
  end if;

  -- Add or update destination stock
  if exists (select 1 from public.stock where warehouse_id = p_to and sku = p_sku) then
    update public.stock
    set qty = qty + p_qty
    where warehouse_id = p_to
      and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return remaining qty at source
  if exists (select 1 from public.stock where warehouse_id = p_from and sku = p_sku) then
    return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);
  else
    return 0;
  end if;
end;
$$;

