declare
  v_from_qty integer;
  v_to_exists boolean;
  v_source_stock record;
begin
  -- Rule R4: Caller must be staff of the source warehouse
  if not public.is_warehouse_staff(p_from, auth.uid()) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  -- Rule R4: Quantity must be positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  -- Rule R4: Source and destination must be different warehouses
  if p_from = p_to then
    raise exception 'Source and destination cannot be the same warehouse';
  end if;

  -- Rule R4: Destination warehouse must exist
  select exists(select 1 from public.warehouses where id = p_to) into v_to_exists;
  if not v_to_exists then
    raise exception 'Destination warehouse does not exist';
  end if;

  -- Rule R4: Source must have enough stock
  select qty into v_from_qty from public.stock where warehouse_id = p_from and sku = p_sku;
  if v_from_qty is null or v_from_qty < p_qty then
    raise exception 'Source does not have enough stock';
  end if;

  -- Deduct from source
  update public.stock set qty = qty - p_qty where warehouse_id = p_from and sku = p_sku;

  -- Insert or update destination stock
  insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty)
    on conflict (warehouse_id, sku) do update set qty = stock.qty + excluded.qty;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
    values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return remaining quantity at source
  return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);
end;
$$;

