-- Block all modifications to stock and transfers
create policy "Stock no modifications" on public.stock
  for all using (false);

create policy "Transfers no modifications" on public.transfers
  for all using (false);

-- Transfer stock RPC
create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
)
returns integer language sql strict as $$
declare
  v_from_qty integer;
  v_to_exists boolean;
begin
  -- Rule R4 checks
  if p_qty <= 0 then
    raise exception 'Quantity must be positive';
  end if;

  if p_from = p_to then
    raise exception 'Source and destination must be different';
  end if;

  -- Check caller is staff of source warehouse
  if not is_staff_of_warehouse(auth.uid(), p_from) then
    raise exception 'Caller is not staff of the source warehouse';
  end if;

  -- Check source has enough stock
  select qty into v_from_qty from public.stock where warehouse_id = p_from and sku = p_sku;
  if v_from_qty is null or v_from_qty < p_qty then
    raise exception 'Insufficient stock at source warehouse';
  end if;

  -- Check destination exists
  select exists(select 1 from public.warehouses where id = p_to) into v_to_exists;
  if not v_to_exists then
    raise exception 'Destination warehouse does not exist';
  end if;

  -- Update source stock
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  if not found then
    raise exception 'Source stock row not found';
  end if;

  -- Update or insert destination stock
  if exists(select 1 from public.stock where warehouse_id = p_to and sku = p_sku) then
    update public.stock
    set qty = qty + p_qty
    where warehouse_id = p_to and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return remaining quantity at source
  return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);
end;
$$;

