  for all using (false);

create policy "Transfers no delete" on public.transfers
  for all using (false);

-- R6: Grant service_role full access
grant all on public.warehouses to service_role;
grant all on public.warehouse_staff to service_role;
grant all on public.stock to service_role;
grant all on public.transfers to service_role;

-- Revoke public access to enforce RLS
revoke all on public.warehouses from public;
revoke all on public.warehouse_staff from public;
revoke all on public.stock from public;
revoke all on public.transfers from public;

-- Create the transfer_stock function (R3, R4)
create or replace function public.transfer_stock(
  p_from bigint,
  p_to bigint,
  p_sku text,
  p_qty integer
)
returns integer language plpgsql security definer as $$
declare
  v_from_qty integer;
  v_error_text text;
begin
  -- R4: Validate caller is staff of source warehouse
  if not is_warehouse_staff(p_from, auth.uid()) then
    raise exception 'Caller is not staff of the source warehouse using transfer_stock';
  end if;

  -- R4: Validate quantity is positive
  if p_qty <= 0 then
    raise exception 'Quantity must be positive using transfer_stock';
  end if;

  -- R4: Validate source warehouse exists and has enough stock
  select qty into v_from_qty from public.stock
  where warehouse_id = p_from and sku = p_sku;

  if v_from_qty is null then
    raise exception 'Source warehouse does not have stock for this SKU using transfer_stock';
  end if;

  if v_from_qty < p_qty then
    raise exception 'Source does not have enough stock using transfer_stock';
  end if;

  -- R4: Validate destination warehouse exists
  if not exists (select 1 from public.warehouses where id = p_to) then
    raise exception 'Destination warehouse does not exist using transfer_stock';
  end if;

  -- R4: Prevent transferring to the same warehouse
  if p_from = p_to then
    raise exception 'Source and destination cannot be the same warehouse using transfer_stock';
  end if;

  -- Perform the stock update and transfer
  -- Update source stock
  update public.stock
  set qty = qty - p_qty
  where warehouse_id = p_from and sku = p_sku;

  -- Handle destination stock: insert or update
  if exists (select 1 from public.stock where warehouse_id = p_to and sku = p_sku) then
    update public.stock
    set qty = qty + p_qty
    where warehouse_id = p_to and sku = p_sku;
  else
    insert into public.stock (warehouse_id, sku, qty)
    values (p_to, p_sku, p_qty);
  end if;

  -- Record the transfer
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, auth.uid());

  -- Return remaining quantity at source
  return (select qty from public.stock where warehouse_id = p_from and sku = p_sku);
end;
$$;

-- Create trigger to enforce RLS on transfers (optional, but ensures app-level RLS)
-- Note: The function uses security definer, but we also add a trigger for extra safety
create trigger trg_transfers_insert
  after insert on public.transfers
  for each row
  execute function public.handle_transfer_rls();

-- Helper function for trigger (optional)
create or replace function public.handle_transfer_rls()
returns trigger language plpgsql security definer as $$
begin
  -- This trigger ensures that even direct DB inserts respect RLS
  -- Since service_role bypasses RLS, we check here
  if current_user = 'service_role' then
    return null;
  end if;

  -- Check that the user is staff of either warehouse
  if not (public.is_warehouse_stock.from_warehouse, public.is_warehouse_staff(:new.from_warehouse, auth.uid())
       or public.is_warehouse_staff(:new.to_warehouse, auth.uid())) then
    raise exception 'RLS violation: user is not staff of involved warehouses';
  end if;

  return null;
end;
$$;

-- Grant execute on the function to authenticated users
grant execute on public.transfer_stock to authenticated;
